#!/usr/bin/env node
/**
 * Seeds the Marketplace with 100 original TTRPG listings under a "Fog of the Dragon Originals" creator.
 *
 * Usage (pick one auth method):
 *
 *   # Method 1: Email/password (if the user has a password)
 *   node tools/seed-marketplace.js --email=USER_EMAIL --password=USER_PASSWORD [--resume] [--delay=8000] [--dry-run]
 *
 *   # Method 2: Service role key (for GitHub OAuth users who have no password)
 *   node tools/seed-marketplace.js --service-role-key=YOUR_KEY --user-id=YOUR_UUID [--resume] [--delay=8000] [--dry-run]
 *
 *   Get the service role key from: Supabase Dashboard > Settings > API > service_role key
 *   Get your user ID from: Supabase Dashboard > Auth > Users > click your user > copy the UUID
 *
 * The user must already exist in Supabase Auth. That user becomes the "FOD Originals" creator.
 * Cover images are generated via Pollinations.ai and uploaded to Supabase Storage.
 *
 * Requirements: Node 18+ (uses native fetch). Reads Supabase URL/key from JS/config/supabase-config.js.
 */

const fs = require('fs');
const path = require('path');
const https = require('https');
const http = require('http');

const REPO = path.resolve(__dirname, '..');
const COVER_DIR = path.join(REPO, 'Assets', 'Images', 'marketplace');
const MANIFEST_PATH = path.join(COVER_DIR, 'seed-manifest.json');

// Parse args
const args = process.argv.slice(2);
function arg(name) { const a = args.find(a => a.startsWith('--' + name + '=')); return a ? a.split('=').slice(1).join('=') : null; }
const EMAIL = arg('email');
const PASSWORD = arg('password');
const SERVICE_ROLE_KEY = arg('service-role-key');
const USER_ID = arg('user-id');
const RESUME = args.includes('--resume');
const DRY_RUN = args.includes('--dry-run');
const DELAY = parseInt(arg('delay') || '8000', 10);
const CREATOR_NAME = 'Fog of the Dragon Originals';

const HAS_PASSWORD_AUTH = EMAIL && PASSWORD;
const HAS_SERVICE_AUTH = SERVICE_ROLE_KEY && USER_ID;

if (!HAS_PASSWORD_AUTH && !HAS_SERVICE_AUTH) {
  console.error('Usage (pick one):\n' +
    '  node tools/seed-marketplace.js --email=EMAIL --password=PASS [--resume] [--delay=8000]\n' +
    '  node tools/seed-marketplace.js --service-role-key=KEY --user-id=UUID [--resume] [--delay=8000]');
  process.exit(1);
}

// Read Supabase config from the generated browser config file
function readConfig() {
  const cfgPath = path.join(REPO, 'JS', 'config', 'supabase-config.js');
  if (!fs.existsSync(cfgPath)) { console.error('JS/config/supabase-config.js not found. Run: node tools/write-supabase-config.mjs'); process.exit(1); }
  const src = fs.readFileSync(cfgPath, 'utf8');
  const m = src.match(/\{[\s\S]*\}/);
  if (!m) { console.error('Could not parse supabase-config.js'); process.exit(1); }
  return JSON.parse(m[0]);
}

const CONFIG = readConfig();
const SB_URL = CONFIG.url;
const SB_KEY = CONFIG.publishableKey;

// ---- Supabase REST helpers ----
let ACCESS_TOKEN = null;

async function sbFetch(endpoint, opts) {
  const url = SB_URL + endpoint;
  const apikey = HAS_SERVICE_AUTH ? SERVICE_ROLE_KEY : SB_KEY;
  const authHeader = HAS_SERVICE_AUTH
    ? { 'Authorization': 'Bearer ' + SERVICE_ROLE_KEY }
    : ACCESS_TOKEN ? { 'Authorization': 'Bearer ' + ACCESS_TOKEN } : {};
  const headers = {
    'apikey': apikey,
    'Content-Type': 'application/json',
    ...authHeader,
    ...(opts.headers || {}),
  };
  const res = await fetch(url, { ...opts, headers });
  const text = await res.text();
  let data;
  try { data = JSON.parse(text); } catch { data = text; }
  if (!res.ok) throw new Error(`Supabase ${res.status}: ${typeof data === 'string' ? data : JSON.stringify(data)}`);
  return data;
}

async function login() {
  if (HAS_SERVICE_AUTH) {
    ACCESS_TOKEN = null;
    console.log('Using service role key for user: ' + USER_ID);
    return { id: USER_ID };
  }
  const data = await sbFetch('/auth/v1/token?grant_type=password', {
    method: 'POST',
    body: JSON.stringify({ email: EMAIL, password: PASSWORD }),
  });
  ACCESS_TOKEN = data.access_token;
  console.log('Logged in as ' + data.user.email + ' (id: ' + data.user.id + ')');
  return data.user;
}

async function insertListing(row) {
  return sbFetch('/rest/v1/marketplace_listings', {
    method: 'POST',
    headers: { 'Prefer': 'return=representation' },
    body: JSON.stringify(row),
  });
}

// ---- Pollinations.ai image fetch ----
function fetchImage(url, timeout) {
  return new Promise((resolve, reject) => {
    const proto = url.startsWith('https') ? https : http;
    const req = proto.get(url, { timeout: timeout || 90000 }, res => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        return fetchImage(res.headers.location, timeout).then(resolve, reject);
      }
      if (res.statusCode !== 200) {
        res.resume();
        return reject(new Error('HTTP ' + res.statusCode));
      }
      const chunks = [];
      res.on('data', c => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks)));
      res.on('error', reject);
    });
    req.on('error', reject);
    req.on('timeout', () => { req.destroy(); reject(new Error('timeout')); });
  });
}

function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }

function slug(text) {
  return text.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 60);
}

async function generateCover(title, artPrompt, index) {
  const filename = slug(title) + '.webp';
  const filepath = path.join(COVER_DIR, filename);
  if (RESUME && fs.existsSync(filepath) && fs.statSync(filepath).size > 5000) {
    console.log(`  cover: reusing ${filename}`);
    return filename;
  }
  const encoded = encodeURIComponent(artPrompt);
  const url = `https://pollinations.ai/p/${encoded}?width=768&height=768&nologo=true`;
  for (let attempt = 1; attempt <= 5; attempt++) {
    try {
      process.stdout.write(`  cover attempt ${attempt}/5...`);
      const buf = await fetchImage(url, 90000);
      if (buf.length < 5000) { console.log(' too small, retrying'); await sleep(DELAY); continue; }
      fs.writeFileSync(filepath, buf);
      console.log(` OK (${Math.round(buf.length / 1024)} KB)`);
      return filename;
    } catch (e) {
      console.log(` ${e.message}`);
      if (attempt < 5) await sleep(DELAY);
    }
  }
  console.log('  cover FAILED');
  return null;
}

// ---- Upload to Supabase storage ----
async function uploadCover(userId, listingId, filepath) {
  const storagePath = `${userId}/${listingId}/media/cover.webp`;
  const fileData = fs.readFileSync(filepath);
  const url = SB_URL + '/storage/v1/object/marketplace/' + storagePath;
  const apikey = HAS_SERVICE_AUTH ? SERVICE_ROLE_KEY : SB_KEY;
  const uploadHeaders = {
    'apikey': apikey,
    'Content-Type': 'image/webp',
    'x-upsert': 'true',
  };
  if (HAS_SERVICE_AUTH) uploadHeaders['Authorization'] = 'Bearer ' + SERVICE_ROLE_KEY;
  else if (ACCESS_TOKEN) uploadHeaders['Authorization'] = 'Bearer ' + ACCESS_TOKEN;
  const res = await fetch(url, {
    method: 'POST',
    headers: uploadHeaders,
    body: fileData,
  });
  if (!res.ok) {
    const text = await res.text();
    throw new Error('Storage upload failed: ' + res.status + ' ' + text);
  }
  return storagePath;
}

