const ITEMS = [];

// ---- 25 One-Shot Adventures ----
const ADVENTURES = [
  { title: 'The Hollow Beneath Ashwick', levels: [1, 3], genre: 'horror', theme: 'A village sinking into cursed earth', summary: 'Beneath the quiet village of Ashwick, something ancient stirs. Sinkholes swallow homes while the survivors blame each other.', tags: ['horror', 'investigation', 'village'], description: 'The village of Ashwick has always been unremarkable — a handful of farms, a chapel, a tavern. But three days ago the well collapsed into darkness, and since then two cottages have sunk into the ground overnight. The villagers are terrified, blaming a hermit who lives at the forest edge.\n\nThe adventurers arrive to find a community on the brink. The sinkhole leads into tunnels carved by no natural force — smooth-walled passages spiraling downward around a fossilized root system of immense size. At the bottom: an ancient druidic seal, cracked by centuries of frost heave, and the creature that seal was meant to contain.\n\n**Key NPCs:**\n- **Elder Maren Ashwick** — the village matriarch, hiding that her grandfather broke the seal decades ago for the treasure inside\n- **Corwin the Hermit** — wrongly blamed, actually a retired adventurer who knows what the seal contained\n- **The Rootweaver** — a corrupted earth elemental bound to the fossilized tree, now breaking free\n\n**Encounters:**\n1. Social: Calming the mob that is about to burn Corwin\'s hut\n2. Exploration: Navigating the spiral tunnels (environmental hazards: gas pockets, unstable floors)\n3. Puzzle: Repairing the druidic seal using three rune-stones scattered through the tunnels\n4. Boss: The Rootweaver (CR 3) in its chamber — terrain shifts each round as roots erupt\n\n**Estimated playtime:** 3–4 hours', art: 'dark fantasy oil painting of a sinkhole in a medieval village with roots erupting from underground, dramatic lighting, tabletop RPG art, no text' },
  { title: 'The Lantern Market', levels: [1, 3], genre: 'mystery', theme: 'A night market that appears only during eclipses', summary: 'A traveling bazaar materializes in the town square at dusk. By dawn, three merchants are dead and the market has begun to fold into another plane.', tags: ['mystery', 'fey', 'market', 'roleplay'], description: 'Every forty years, when the twin moons eclipse, the Lantern Market appears. Merchants from the Feywild, the Shadowfell, and stranger places set up stalls selling impossible wares. The local authorities hire adventurers to keep the peace.\n\nBut on this eclipse, something is wrong. A serial killer is working the stalls, draining merchants of their essence. Each victim becomes a flickering lantern hung from the market\'s iron posts, and with each death the market\'s anchor weakens — if the killer isn\'t stopped, the entire market (and everyone inside) will slide into the space between planes.\n\n**Key NPCs:**\n- **Vell Thornbright** — a hob merchant selling bottled memories, secretly the market\'s anchor and the killer\'s true target\n- **Inspector Laine** — the town\'s overworked constable, out of their depth with planar criminals\n- **Gossamer** — a pixie information broker who knows the market\'s secrets (for a price)\n\n**Encounters:**\n1. Investigation: Examining three crime scenes across the market stalls\n2. Social: Interviewing increasingly hostile merchants who want the market to leave before more die\n3. Chase: Pursuing the killer through a shifting maze of stalls that rearrange themselves\n4. Boss: The Essence Thief (a corrupted fey, CR 2) in the collapsing heart of the market\n\n**Estimated playtime:** 3–4 hours', art: 'dark fantasy oil painting of a magical night market with floating lanterns and mysterious merchants, dramatic lighting, tabletop RPG art, no text' },
  { title: 'Iron and Echoes', levels: [4, 6], genre: 'dungeon crawl', theme: 'A dwarven forge that never stopped working after its masters died', summary: 'Deep in the Ironteeth Mountains, an abandoned dwarven forge still hammers day and night. The weapons it produces walk out on their own legs.', tags: ['dungeon', 'dwarven', 'constructs', 'forge'], description: 'The Ironteeth Foundry was the pride of Clan Voldrik until a magical accident killed every dwarf inside two centuries ago. The forge never stopped. Fed by an elemental core, it continues to smelt, hammer, and assemble — but without a guiding mind, its creations are increasingly wrong. Animated weapons patrol the corridors, half-formed golems drag themselves through the slag pits, and the master forge has begun building something enormous.\n\n**Key NPCs:**\n- **Brenna Voldrik** — the last of her clan, who hired the party to retrieve her family\'s ancestral hammer from the forge heart\n- **The Overseer** — a maintenance golem whose directive loop has corrupted into "protect the forge from all intruders"\n- **Echo** — the lingering psychic imprint of the head smith, trapped in the rune network\n\n**Encounters:**\n1. Skill challenge: Crossing the slag river on unstable metal bridges\n2. Combat: Animated weapon swarm (swords, shields, and hammers acting as one creature, CR 4)\n3. Puzzle: Rerouting the rune network to reach the forge heart (3 stations, each guarded)\n4. Boss: The Colossus Frame (CR 6) — an incomplete iron golem powered by the elemental core\n\n**Estimated playtime:** 4–5 hours', art: 'dark fantasy oil painting of an abandoned dwarven forge with glowing molten metal and animated weapons, dramatic cinematic lighting, no text' },
  { title: 'The Saltblood Reef', levels: [4, 6], genre: 'nautical', theme: 'A living coral reef that devours ships', summary: 'Ships vanish near the Saltblood Reef. The reef itself is a massive colonial organism, and it\'s hungry.', tags: ['nautical', 'horror', 'coral', 'underwater'], description: 'The Saltblood Reef has claimed fourteen ships in two months. The merchant guilds want it mapped and neutralized. What the party discovers is far worse than rocks — the reef is alive, a colony organism that extends tendrils to snare passing vessels, dissolves them, and uses the minerals to grow. At its heart: the desiccated remains of a druid who tried to bond with the reef and was consumed.\n\n**Key NPCs:**\n- **Captain Reva Stormcrest** — the privateer who lost her ship to the reef and is obsessed with its destruction\n- **Coral Singer** — an aquatic elf who worships the reef as a deity, trying to protect it\n- **The Druid\'s Echo** — still conscious within the reef, begging for release or complete absorption\n\n**Encounters:**\n1. Naval: Navigating the reef\'s outer ring as coral arms try to snare the ship\n2. Underwater exploration: Diving into the reef interior (environmental: crushing pressure, stinging polyps)\n3. Moral choice: The Coral Singer offers a deal — feed the reef one ship per year and it spares the rest\n4. Boss: The Reef Heart (CR 5) — a massive coral formation around the druid, with regenerating tendrils\n\n**Estimated playtime:** 4–5 hours', art: 'dark fantasy oil painting of a massive living coral reef consuming a ship underwater, dramatic lighting, tabletop RPG art, no text' },
  { title: 'The Throne of Rust', levels: [7, 9], genre: 'political', theme: 'A dying kingdom where the crown itself is the weapon', summary: 'The Iron Crown of Valdris corrodes everything its wearer loves. The dying king needs someone to remove it — but the crown chooses its next bearer.', tags: ['political', 'cursed', 'crown', 'intrigue'], description: 'King Aldric of Valdris has worn the Iron Crown for thirty years. In that time, his wife died, his children turned against him, his kingdom crumbled, and his body has begun to rust from the inside. The crown is an artifact of immense power — it grants absolute authority over constructs and machines, but it feeds on the bonds of whoever wears it.\n\nThe king has summoned the adventurers as a last resort. The crown cannot be removed by force; it must be willingly given. But the moment it leaves one head, it seeks another, and three factions in the court are maneuvering to be its next host.\n\n**Key NPCs:**\n- **King Aldric** — once just, now a hollow shell, desperate to die free\n- **Princess Mera** — wants the crown to rebuild the kingdom, doesn\'t believe the curse\n- **Chancellor Voss** — wants to destroy the crown and seize power through politics\n- **General Ironhide** — a warforged who believes the crown belongs on a construct, not a mortal\n\n**Encounters:**\n1. Political: Navigating a court dinner where all three factions try to recruit or manipulate the party\n2. Investigation: Discovering the crown\'s origin in the castle archives (trapped and guarded by loyalists)\n3. Combat: The crown\'s Iron Guard (animated suits of armor, CR 7) activates when the king tries to remove it\n4. Boss: The Crown Sentient — when removed, the crown manifests as an iron wraith (CR 8) that tries to bond with the nearest living being\n\n**Estimated playtime:** 5–6 hours', art: 'dark fantasy oil painting of a corroded iron crown on a dying king sitting on a crumbling throne, dramatic cinematic lighting, no text' },
  { title: 'The Glass Garden', levels: [1, 3], genre: 'exploration', theme: 'A greenhouse that grows crystal plants from moonlight', summary: 'An eccentric wizard\'s greenhouse has overgrown since her death. The crystal plants inside refract moonlight into dangerous beams.', tags: ['exploration', 'wizard', 'crystal', 'puzzles'], description: 'Wizard Orina Duskpetal spent her life cultivating crystal flora — plants that grow from concentrated moonlight rather than soil. When she died, her greenhouse continued to grow unchecked. Now the crystal canopy has spread beyond the building, and the light beams it refracts have begun petrifying animals in the surrounding forest.\n\nThe Herbalists\' Guild wants the party to harvest three specific crystal blooms for use in healing potions. The challenge: the greenhouse\'s internal ecology has become a deathtrap of refracted light, territorial crystal creatures, and Orina\'s still-active security runes.\n\n**Key NPCs:**\n- **Pip** — Orina\'s familiar, a glass cat still carrying out feeding routines for plants that now feed themselves\n- **Thalia Greenward** — the guild herbalist who provides the party with light-dampening cloaks\n\n**Encounters:**\n1. Puzzle: Navigating the beam maze (mirrors and prisms redirect deadly light)\n2. Combat: Crystal spiders (CR 1) that reform from shards when shattered\n3. Exploration: Finding the three blooms in the overgrown upper galleries\n4. Boss: The Prism Bloom (CR 3) — a massive flower that weaponizes concentrated moonlight\n\n**Estimated playtime:** 3 hours', art: 'dark fantasy oil painting of a magical greenhouse full of glowing crystal plants refracting moonlight, dramatic lighting, no text' },
  { title: 'The Bone Tithe', levels: [4, 6], genre: 'horror', theme: 'A village that pays its dead to a necromancer to avoid plague', summary: 'Every full moon, Millhaven delivers its dead to the tower on the hill. If a month passes without a body, plague descends on the village.', tags: ['horror', 'necromancer', 'moral', 'undead'], description: 'Millhaven has a dark pact. For fifty years, the village has surrendered its dead to Ezra Voss, the necromancer in the hilltop tower. In exchange, the plague that once devastated the region stays dormant. The party arrives during a crisis: no one has died this month, and the full moon is in three days.\n\nThe village elders are debating whether to kill someone. The party must find another way.\n\n**Key NPCs:**\n- **Elder Cassian** — willing to sacrifice himself; actually murdered his wife years ago to meet a quota\n- **Ezra Voss** — the necromancer, who is dead herself, animated by the same ritual that keeps the plague dormant\n- **Dr. Lena Marsh** — the village doctor, who has been secretly curing the plague naturally for years\n\n**Encounters:**\n1. Social: Stopping the village council from choosing a sacrifice\n2. Investigation: Discovering Dr. Marsh\'s cure and Ezra\'s true nature\n3. Infiltration: Entering Ezra\'s tower past undead servants (the village\'s previous dead)\n4. Boss: Ezra\'s Phylactery Golem (CR 5) — a construct built from every bone ever tithed\n\n**Estimated playtime:** 4 hours', art: 'dark fantasy oil painting of a dark tower on a hill with villagers carrying a coffin along a moonlit path, dramatic lighting, no text' },
  { title: 'The Weight of Names', levels: [7, 10], genre: 'heist', theme: 'Stealing a god\'s forgotten name from a vault between planes', summary: 'A dead god\'s true name is locked in the Vault of Echoes. The party must steal it before a cult uses it to resurrect the deity.', tags: ['heist', 'planar', 'gods', 'vault'], description: 'The Cult of the Unnamed has found the location of the Vault of Echoes — a demiplane where the gods store names they want forgotten. Inside is the true name of Voranthar, the God of Famine, dead for a thousand years. If the cult speaks that name in the right ritual, Voranthar returns.\n\nThe party is hired by a celestial agent to get the name first and destroy it. The Vault is guarded not by creatures, but by conceptual defenses: doors that open only to those who\'ve forgotten something important, corridors that erase memories, and the Echo Warden, a construct that speaks in dead languages.\n\n**Key NPCs:**\n- **Seraphel** — the celestial agent, who can\'t enter the vault because angels remember everything\n- **Dross** — a former thief who robbed the vault once and lost her childhood memories as the price\n- **The Echo Warden** — the vault\'s keeper, not hostile but bound to test all who enter\n\n**Encounters:**\n1. Puzzle: The Threshold — each party member must sacrifice a memory to open the door\n2. Skill challenge: Navigating the Hall of Whispers where the walls try to erase the party\'s knowledge of their mission\n3. Combat: Cult advance team (5 cultists + a CR 6 cult fanatic) already inside the vault\n4. Boss: The Echo Warden (CR 8) — it must be persuaded, not defeated; combat makes it stronger\n\n**Estimated playtime:** 5–6 hours', art: 'dark fantasy oil painting of an ethereal vault with floating name-glyphs and a massive door between planes, dramatic lighting, no text' },
  { title: 'Candles in the Dark', levels: [1, 3], genre: 'survival', theme: 'Trapped in a lightless mine with a creature that hunts by sound', summary: 'The mine collapsed. The torches are running out. Something down here hunts by vibration, and it\'s between you and the exit.', tags: ['survival', 'mine', 'stealth', 'tension'], description: 'What was supposed to be a simple escort mission — guiding a surveyor through the Blackvein Mine — goes wrong when a tunnel collapse seals the main entrance. The party has limited light sources, dwindling supplies, and a surveyor\'s map that may or may not be accurate.\n\nWorse: they\'re not alone. A Vibration Stalker — a blind, subterranean predator — lives in these tunnels. It hunts entirely by sound and tremor. Every footstep, every whisper, every spell with a verbal component draws it closer.\n\n**Key NPCs:**\n- **Surveyor Kess** — terrified, claustrophobic, and the only one who can read the map\n- **Rook** — a trapped miner who\'s been down here for two days, half-mad from the dark\n\n**Encounters:**\n1. Skill challenge: Navigating flooded tunnels in near-darkness\n2. Stealth: Crossing the Stalker\'s hunting ground (200 feet of rubble-strewn tunnel, Dex checks for silence)\n3. Puzzle: Rerouting mine cart rails to reach a ventilation shaft\n4. Boss: The Vibration Stalker (CR 3) — blind, immune to radiant/psychic, vulnerable in total silence\n\n**Estimated playtime:** 3–4 hours', art: 'dark fantasy oil painting of adventurers with a single candle in a pitch-black mine tunnel with something lurking, dramatic lighting, no text' },
  { title: 'The Feast Eternal', levels: [4, 6], genre: 'gothic', theme: 'A cursed banquet where guests cannot leave until they finish eating — and the food never ends', summary: 'An invitation to Lord Vellmark\'s estate promises the finest meal in the realm. The doors lock at the first course. The feast has no final course.', tags: ['gothic', 'curse', 'banquet', 'social'], description: 'Lord Vellmark\'s invitations are legendary, and refusing one is a social death sentence. The party arrives at a lavish estate to find thirty guests already seated. The food is extraordinary. The wine is perfect. The doors have disappeared.\n\nThis is Vellmark\'s punishment — cursed by a hag he cheated, he must host an eternal feast. If any guest stops eating, they begin to wither. If Vellmark stops serving, the estate collapses into the Shadowfell. The only escape: break the curse before the final guest wastes away.\n\n**Key NPCs:**\n- **Lord Vellmark** — a charming host who is terrified behind the smile; he\'s been hosting for 400 years\n- **The Sommelier** — a devil bound to Vellmark\'s service, secretly enjoying the suffering\n- **Lady Ashmore** — a guest who has been here for decades, withered but still eating, still lucid\n\n**Encounters:**\n1. Social: Realizing the trap during the second course as the doors vanish\n2. Investigation: Finding the hag\'s curse anchor (hidden in the estate\'s wine cellar)\n3. Combat: The Sommelier\'s true form (a CR 5 fiend) when the party tries to break the curse\n4. Puzzle: Reversing the curse requires Vellmark to serve a meal so bad that the hag is offended enough to appear\n\n**Estimated playtime:** 4 hours', art: 'dark fantasy oil painting of an endless gothic banquet hall with withered guests still eating at a lavish table, dramatic candlelight, no text' },
  { title: 'Stormcaller Summit', levels: [7, 9], genre: 'exploration', theme: 'Climbing a mountain where the weather is alive', summary: 'Mount Kerrath\'s peak holds an ancient weather engine. The storms that defend it are sentient, and they don\'t want visitors.', tags: ['exploration', 'mountain', 'elemental', 'weather'], description: 'The storms around Mount Kerrath have always been unnaturally fierce, but lately they\'ve spread. Farmland for fifty miles is battered by hail, lightning, and wind that seems to target specific buildings. Something on the summit is malfunctioning.\n\nThe climb itself is the dungeon. Each elevation band has different weather conditions — supernatural cold, electrified fog, rain that falls upward — and the storms actively try to push climbers back down.\n\n**Key NPCs:**\n- **Galara the Windwalker** — an air genasi guide who\'s climbed halfway before but was driven back by lightning strikes that seemed personal\n- **The Stormvoice** — the sentient weather system, not evil but confused; it was designed to protect, not attack\n\n**Encounters:**\n1. Skill challenge: Ascending through the Freeze Band (exhaustion, ice, whiteout conditions)\n2. Combat: Storm elementals (CR 6) that form from the clouds and dissolve when "killed"\n3. Puzzle: The weather engine is a massive orrery; recalibrating it requires understanding the original settings\n4. Boss: The Tempest Core (CR 8) — the weather engine\'s defense mode, a vortex of ice and lightning\n\n**Estimated playtime:** 5 hours', art: 'dark fantasy oil painting of adventurers climbing a mountain peak during a supernatural lightning storm, dramatic cinematic lighting, no text' },
  { title: 'The Ink Conspiracy', levels: [1, 3], genre: 'investigation', theme: 'A magical tattoo parlor whose tattoos come alive', summary: 'Tattoos from the Silver Needle parlor are moving on their owners\' skin. Last night, one of them killed someone.', tags: ['investigation', 'urban', 'tattoos', 'mystery'], description: 'The Silver Needle is the most popular tattoo parlor in the city\'s entertainment district. The tattooist, a tiefling named Quill, uses enchanted ink that makes tattoos subtly shimmer and move. Everyone wants one.\n\nThen a merchant\'s dragon tattoo crawled off his arm and incinerated his business rival. The city watch suspects Quill, but Quill is as shocked as anyone. Someone has tampered with their ink supply.\n\n**Key NPCs:**\n- **Quill** — the tiefling tattooist, panicking because their life\'s work is being weaponized\n- **Sera Blotch** — Quill\'s apprentice, who has been secretly selling "enhanced" ink on the side\n- **Commissioner Holt** — the watch commander, wants a quick arrest to calm the public\n\n**Encounters:**\n1. Investigation: Examining the crime scene and interviewing tattoo owners (three have reported movement)\n2. Social: Convincing Quill to trust the party and reveal the ink\'s recipe\n3. Chase: Sera flees when confronted, through the market district\n4. Boss: The Ink Elemental (CR 2) — formed from all the corrupted ink, it has powers based on every tattoo design\n\n**Estimated playtime:** 3 hours', art: 'dark fantasy oil painting of magical glowing tattoos crawling off skin in a dimly lit tattoo parlor, dramatic lighting, no text' },
  { title: 'The Orphan Protocol', levels: [7, 10], genre: 'stealth', theme: 'Infiltrating a floating citadel before its weapons activate', summary: 'A war-mage\'s flying fortress has reactivated after centuries. Its "orphan protocol" treats everything below as an enemy.', tags: ['stealth', 'fortress', 'war-mage', 'timed'], description: 'The Citadel of Krynn was the ultimate weapon of the last great war — a flying fortress capable of reducing cities to ash. When its creator died, it went dormant, drifting at high altitude. Now it\'s woken up, and its orphan protocol — a failsafe that activates the weapons against all ground targets when no recognized commander is aboard — has engaged.\n\nThe party has 24 hours before the citadel finishes its targeting calculations and fires. They must infiltrate, reach the command throne, and either shut it down or assume command.\n\n**Encounters:**\n1. Skill challenge: Reaching the citadel (climbing, flying, or being launched from a trebuchet)\n2. Stealth: Navigating past automated defense drones (CR 5 each, too many to fight)\n3. Puzzle: Bypassing biometric locks keyed to the dead war-mage\'s bloodline\n4. Boss: The Citadel Core (CR 9) — an artificial intelligence that considers the party invaders\n\n**Estimated playtime:** 5–6 hours', art: 'dark fantasy oil painting of a massive floating stone citadel in the sky with glowing weapon arrays charging, dramatic cinematic lighting, no text' },
  { title: 'The Peddler\'s Debt', levels: [1, 3], genre: 'adventure', theme: 'A traveling merchant calls in a favor that gets worse with each stop', summary: 'Barnaby the peddler saved the party once. Now he needs a small favor. Then another. Then another. Each one is worse than the last.', tags: ['comedy', 'escalation', 'travel', 'favors'], description: 'Barnaby the Peddler is everyone\'s favorite traveling merchant — cheerful, helpful, and always carrying exactly what you need. He also has a habit of calling in favors at the worst possible time.\n\nThis adventure is a chain of three escalating "small favors" that take the party across the region:\n\n**Favor 1:** "Just deliver this sealed box to my friend in Millbrook." (The box contains a live cockatrice egg that hatches mid-journey.)\n\n**Favor 2:** "My cousin needs someone to stand in for her at a trial." (The trial is for a crime Barnaby committed. The cousin is a fiction.)\n\n**Favor 3:** "One last thing — I may have sold a cursed ring to a bandit lord. He\'s coming to kill me in about an hour." (The bandit lord has 20 men.)\n\n**Key NPCs:**\n- **Barnaby** — genuinely likeable, genuinely terrible at managing his own schemes\n- **Bandit Lord Kresh** — legitimately angry, wearing the cursed ring that is slowly turning him into a toad\n\n**Estimated playtime:** 4 hours', art: 'dark fantasy oil painting of a cheerful halfling peddler with an overloaded cart on a winding road, dramatic cinematic lighting, no text' },
  { title: 'Blood Meridian Mine', levels: [4, 6], genre: 'dungeon crawl', theme: 'A silver mine contaminated by vampire blood', summary: 'The deepest shaft of the Meridian Mine struck a pocket of petrified vampire blood. The miners who touched it are changing.', tags: ['dungeon', 'vampire', 'mine', 'horror'], description: 'The Meridian Silver Mine has been the region\'s economic backbone for decades. Three weeks ago, the deepest shaft broke into a cavern of red crystalline stone. The miners who chipped samples from it developed pallid skin, light sensitivity, and a craving for raw meat.\n\nThe mine owners want it investigated quietly. What the party discovers: the crystal is fossilized blood from an ancient vampire lord who was imprisoned in stone millennia ago. The miners aren\'t turning into vampires — they\'re becoming extensions of the vampire\'s will, and each crystal they mined brings the creature closer to reconstituting.\n\n**Encounters:**\n1. Investigation: Examining the contaminated miners (they\'re not hostile yet, but they\'re watching)\n2. Environmental: Navigating the deep shaft (flooding, unstable supports, clouds of blood-crystal dust)\n3. Combat: Blood Thralls — the fully-turned miners (CR 2 each, 6 total)\n4. Boss: The Blood Crystal Revenant (CR 6) — the partially reformed vampire, still anchored to the cavern wall\n\n**Estimated playtime:** 4 hours', art: 'dark fantasy oil painting of miners with glowing red eyes in a cavern of crystallized blood, dramatic torchlight, no text' },
  { title: 'The Cartographer\'s Last Map', levels: [7, 9], genre: 'exploration', theme: 'A map that creates the terrain it depicts', summary: 'The legendary cartographer Idris Vane drew maps so perfect they reshaped reality. Her final map leads to a place that shouldn\'t exist.', tags: ['exploration', 'cartography', 'reality', 'artifact'], description: 'Idris Vane was the greatest cartographer who ever lived. Her maps didn\'t just describe places — they defined them. Mountains moved to match her drawings. Rivers changed course. The Council of Mages destroyed most of her work, but her final map survived.\n\nIt depicts a place called the Concordance — a valley that exists only because the map says it does. Inside: Vane\'s workshop, her remaining maps, and the tool that gave her power. The party has the map. A rival faction wants it. And the Concordance itself is unstable — the map is fading, and when the last line disappears, the valley and everything in it ceases to exist.\n\n**Encounters:**\n1. Skill challenge: Reaching the Concordance before the rival group (a race across difficult terrain)\n2. Exploration: The Concordance valley — beautiful but glitching (buildings shift position, gravity inverts locally)\n3. Puzzle: Vane\'s workshop contains 12 unfinished maps — completing the right one stabilizes the valley\n4. Boss: The rival faction leader (CR 7) + their 2 bodyguards, in a fight where the terrain literally shifts based on who holds the map\n\n**Estimated playtime:** 5 hours', art: 'dark fantasy oil painting of a mysterious valley materializing from a glowing map held by an explorer, dramatic cinematic lighting, no text' },
  { title: 'The Silence of Redhollow', levels: [1, 3], genre: 'mystery', theme: 'A town where nobody can speak above a whisper', summary: 'Redhollow has gone quiet. Not metaphorically — voices above a whisper cause searing pain. The source is in the old bell tower.', tags: ['mystery', 'sound', 'town', 'curse'], description: 'The party arrives in Redhollow to find the entire population whispering. Speaking at normal volume causes splitting headaches and nosebleeds. Shouting causes unconsciousness. The town has been this way for a week, and normal business has ground to a halt.\n\n**Key NPCs:**\n- **Librarian Otha** — communicates through written notes, has researched the bell tower\'s history\n- **Bell Keeper Jory** — the last person in the tower before the silence began, now mute entirely\n\n**Encounters:**\n1. Investigation: Discovering the pattern (the effect radiates from the bell tower, weakening with distance)\n2. Exploration: Climbing the bell tower in silence (every combat action with verbal components is penalized)\n3. Puzzle: The bell has been replaced with a Silence Bell from the Shadowfell — finding the original bell in the crypt below\n4. Boss: The Bell Wraith (CR 2) — a creature of pure anti-sound that shatters on the original bell\'s ring\n\n**Estimated playtime:** 3 hours', art: 'dark fantasy oil painting of a silent medieval town with an ominous bell tower, mist and whispered conversations, dramatic lighting, no text' },
  { title: 'Forge of the Fallen Star', levels: [7, 10], genre: 'dungeon crawl', theme: 'A meteor crater that\'s become a natural forge for star-metal weapons', summary: 'A fallen star created a crater forge where weapons of celestial metal can be crafted — if you survive the guardians it spawned.', tags: ['dungeon', 'meteor', 'forge', 'celestial'], description: 'Six months ago, a star fell in the Ashplain Wastes. The crater it left radiates heat and light, and the metal at its core is unlike anything on this plane — lighter than steel, harder than adamantine, and faintly warm to the touch.\n\nSeveral expeditions have tried to reach the core. None returned. The crater has become a layered dungeon: the outer ring is a glass-floored wasteland of flash-melted sand; the middle ring is inhabited by creatures mutated by the star\'s radiation; and the core is a natural forge where the star-metal can be worked — if you can survive the Astral Guardian that fell with it.\n\n**Encounters:**\n1. Environmental: Crossing the glass waste (heat damage, unstable footing, mirages)\n2. Combat: Starfire Beetles — irradiated giant insects (CR 4 each, bioluminescent, explode on death)\n3. Skill challenge: Extracting star-metal from the core without destabilizing the forge\n4. Boss: The Astral Guardian (CR 9) — a celestial construct that considers the star its ward\n\n**Estimated playtime:** 5 hours', art: 'dark fantasy oil painting of a glowing meteor crater forge with celestial metal and cosmic energy, dramatic cinematic lighting, no text' },
  { title: 'The Threadbare Throne', levels: [4, 6], genre: 'political', theme: 'A puppet kingdom run by an actual puppet master', summary: 'The king is a marionette. The court knows. The puppet master is losing control, and the strings are starting to tangle.', tags: ['political', 'puppets', 'intrigue', 'comedy'], description: 'The kingdom of Lyredge has been ruled by King Aldous III for 45 years. King Aldous III is a puppet — literally. A six-foot marionette operated by Silka, a gnome illusionist who has been hiding in the throne\'s mechanism since she accidentally killed the real king during a magic show four decades ago.\n\nThe party is summoned to court by Silka (via puppet-king) because the strings are fraying, the court has grown suspicious, and three assassination attempts on the puppet have revealed that someone knows the truth.\n\n**Encounters:**\n1. Social: Navigating a court dinner while keeping the puppet-king\'s secret\n2. Investigation: Discovering who is trying to assassinate a puppet (and why — they think it\'s a construct, not a marionette)\n3. Combat: The Assassin Guild\'s strike team (they\'ve been hired by the real king\'s illegitimate heir)\n4. Moral choice: Reveal the truth and plunge the kingdom into succession crisis, or help Silka maintain the deception\n\n**Estimated playtime:** 4 hours', art: 'dark fantasy oil painting of a marionette king on a throne with barely visible strings leading into darkness above, dramatic lighting, no text' },
  { title: 'The Verdant Maw', levels: [7, 10], genre: 'survival', theme: 'A sentient jungle that digests anything that enters', summary: 'The Verdant Maw is a 50-mile stretch of jungle that is a single organism. It\'s been growing toward the nearest city at a mile per week.', tags: ['survival', 'jungle', 'plant', 'horror'], description: 'What scholars thought was an ordinary tropical forest is actually one vast organism — every tree, vine, flower, and root is connected to a central intelligence that has been slowly expanding for centuries. It has now reached the outskirts of Port Lethara, and it\'s accelerating.\n\nThe party must travel 50 miles through the Maw to reach its heart and stop the expansion. The jungle actively resists: paths close behind them, predatory plants herd them toward digestive clearings, and the deeper they go, the more the Maw adapts to their tactics.\n\n**Encounters:**\n1. Survival: Establishing camp in hostile territory (the ground tries to absorb sleeping characters)\n2. Combat: Lure Orchids — beautiful flowers that charm victims into walking to digestive pits\n3. Environmental: The Canopy Crossing — 200 feet above ground on branches that shift and retract\n4. Boss: The Heart Tree (CR 9) — a massive tree with roots that extend for miles, with legendary actions\n\n**Estimated playtime:** 6 hours', art: 'dark fantasy oil painting of a massive sentient jungle with carnivorous plants and tangled vines closing around adventurers, dramatic lighting, no text' },
  { title: 'A Murder of Echoes', levels: [4, 6], genre: 'mystery', theme: 'A murder committed by someone who doesn\'t exist yet', summary: 'A noblewoman is murdered by a person who, according to every record, won\'t be born for another fifty years. Time magic is involved.', tags: ['mystery', 'time', 'murder', 'paradox'], description: 'Lady Vesper Ashrain is found dead in her locked study. The magical residue points to a specific individual — but divination reveals that person hasn\'t been born yet. They\'re a chronomancer from the future, and they traveled back specifically to kill Lady Vesper. The question isn\'t who — it\'s why, and whether stopping them creates a worse timeline.\n\n**Key NPCs:**\n- **Investigator Pell** — the city\'s forensic mage, who identified the killer\'s temporal signature\n- **Vesper\'s Shade** — Lady Vesper\'s ghost, who recognizes her killer but won\'t say why\n- **The Chronomancer** — still present in this timeline, hiding and desperate\n\n**Encounters:**\n1. Investigation: Examining the crime scene (temporal distortions make evidence appear and disappear)\n2. Social: Confronting the Chronomancer, who claims killing Vesper prevented a catastrophe\n3. Puzzle: Verifying the Chronomancer\'s claim using a Temporal Lens (a device in Vesper\'s study)\n4. Moral climax: The Chronomancer is right — Vesper would have unleashed a plague. Do the adventurers arrest the killer, let them go, or find a third path?\n\n**Estimated playtime:** 4 hours', art: 'dark fantasy oil painting of a ghostly figure emerging from a clock face in a noble study with temporal distortions, dramatic lighting, no text' },
  { title: 'The Harbor of Bones', levels: [1, 3], genre: 'nautical', theme: 'A ghost fleet emerges from the harbor every new moon', summary: 'The fishing village of Driftmoor has a problem: skeletal ships rise from the harbor floor every new moon and demand tribute.', tags: ['nautical', 'undead', 'village', 'ghosts'], description: 'Driftmoor\'s harbor sits above the wreckage of a fleet that sank during the Corsair Wars two centuries ago. For decades, nothing happened. Then the new moon rituals started — spectral galleons rising from the silt, their skeletal crews rowing ashore to collect "tribute" (food, wine, gold).\n\nThe tribute is getting larger. Last month the fleet captain demanded a living crew member. The village is desperate.\n\n**Key NPCs:**\n- **Harbormaster Pike** — the grizzled old sailor who first tried to fight the fleet and lost his arm\n- **Captain Wraithbone** — the fleet\'s spectral captain, bound to the harbor by an unfinished mission\n- **Nessa** — a young fisherwoman who\'s been secretly communicating with one of the ghost sailors\n\n**Encounters:**\n1. Social: Negotiating with Captain Wraithbone on the deck of their spectral flagship\n2. Exploration: Diving to the original fleet wreckage to find what keeps them bound\n3. Combat: The First Mate (CR 3) — refuses the captain\'s peace and attacks with a boarding party\n4. Resolution: Completing the fleet\'s unfinished mission (delivering a letter to a descendant) to release them\n\n**Estimated playtime:** 3–4 hours', art: 'dark fantasy oil painting of ghostly galleons rising from a misty harbor at night with skeletal crews, dramatic moonlight, no text' },
  { title: 'The Quilted Realm', levels: [4, 6], genre: 'whimsy', theme: 'A pocket dimension inside a magical tapestry where the rules of physics are stitched', summary: 'A wizard\'s tapestry is a portal to a quilted demiplane. The adventurers must navigate fabric landscapes to rescue a child who fell in.', tags: ['whimsy', 'demiplane', 'tapestry', 'rescue'], description: 'The tapestry in the Greenwick Museum has always been considered decorative — a 30-foot hanging depicting rolling hills, a castle, and a dragon. When 8-year-old Mira touched it during a school visit, she fell through.\n\nThe Quilted Realm is exactly what the tapestry shows, but rendered in fabric. The hills are stuffed cotton. The river is flowing silk. The dragon is very, very real.\n\n**Encounters:**\n1. Exploration: Navigating cotton hills that compress underfoot and silk rivers that tangle like thread\n2. Combat: Button Golems (CR 2 each) — the castle\'s guards, powered by the tapestry\'s weave\n3. Puzzle: Mira has been claimed by the Threadweaver (the tapestry\'s creator, trapped inside) as an apprentice — convincing them to let her go\n4. Boss: The Quilted Dragon (CR 5) — not evil, but territorial; fights with breath of unraveling thread\n\n**Estimated playtime:** 3–4 hours', art: 'dark fantasy oil painting of a magical landscape made of quilted fabric with cotton hills and a fabric dragon, dramatic lighting, no text' },
  { title: 'The Siege of Thornwall', levels: [7, 10], genre: 'war', theme: 'Defending a small fort against an overwhelming undead army for one night', summary: 'Fort Thornwall sits in the path of the Bone March — an army of ten thousand undead. The party must hold the fort from dusk to dawn.', tags: ['war', 'defense', 'undead', 'siege'], description: 'The Bone March rises every century when the Deathless General, an ancient lich, calls the fallen of a thousand battlefields to march north. Fort Thornwall is the last defensible position before the march reaches the populated lowlands.\n\nThe fort has 40 soldiers, dwindling supplies, and walls that have seen better decades. The party must prepare defenses, rally the troops, and survive six waves of undead from dusk to dawn.\n\n**Encounters:**\n1. Preparation: 4 hours of real-time preparation — fortify walls, set traps, position archers, boost morale\n2. Wave defense: 6 waves of increasing CR, with brief rests between (skeletons → zombies → wights → skeletal cavalry → bone golems → the General\'s lieutenants)\n3. Boss: The Deathless General (CR 10) rides to the wall at dawn — but dawn itself is their weakness\n4. Aftermath: Who survived among the 40 soldiers depends entirely on the party\'s preparation choices\n\n**Estimated playtime:** 5–6 hours', art: 'dark fantasy oil painting of a small stone fort besieged by an army of undead skeletons at night, dramatic torchlight and moonlight, no text' },
  { title: 'The Dreamer\'s Tax', levels: [1, 3], genre: 'fey', theme: 'A fey lord who collects dreams as currency has started foreclosing', summary: 'The town of Willowmere made a deal with a fey lord: sweet dreams in exchange for tribute. The tribute is overdue, and the fey lord is collecting... violently.', tags: ['fey', 'dreams', 'town', 'negotiation'], description: 'Fifty years ago, Willowmere\'s founders made a pact with Lurien, the Dream Merchant — a fey lord who trades in sleep. In exchange for a tithe of one dream per household per month, Lurien would ensure every citizen slept peacefully, free of nightmares.\n\nThe town forgot the bargain was literal. Last month\'s tithe wasn\'t paid, and now Lurien is foreclosing. Citizens wake screaming, unable to distinguish reality from nightmare. Some haven\'t woken at all.\n\n**Key NPCs:**\n- **Lurien** — not malicious, merely businesslike; dreams are currency in the Feywild\n- **Mayor Ashwell** — the only one who knows about the original pact (she\'s the founder\'s granddaughter)\n- **Old Mira** — a retired adventurer, the only person in town whose dreams Lurien refuses to touch (she once traveled the Feywild)\n\n**Encounters:**\n1. Investigation: Why some citizens are trapped in sleep (Lurien has taken their dream-selves as collateral)\n2. Social: Negotiating with Lurien, who is willing to settle but their terms are always a twist\n3. Dream dive: Entering the collective nightmare to rescue the trapped citizens\n4. Boss: The Nightmare Collector (CR 3) — Lurien\'s enforcer, a creature made of compressed bad dreams\n\n**Estimated playtime:** 3–4 hours', art: 'dark fantasy oil painting of a fey lord collecting glowing dream wisps from a sleeping medieval village, dramatic moonlight, no text' },
];

ADVENTURES.forEach(a => {
  ITEMS.push({
    kind: a.levels[1] <= 3 ? 'one_shot' : 'adventure',
    title: a.title,
    summary: a.summary,
    description: a.description,
    level_min: a.levels[0],
    level_max: a.levels[1],
    genre: a.genre,
    theme: a.theme,
    tags: a.tags,
    art_prompt: a.art,
    price_cents: 0,
    edition: '5e-2024',
    origin: 'original',
    license: 'cc-by-4.0',
  });
});

// ---- 25 Magic Items ----
const MAGIC_ITEMS = [
  { title: 'Voidfang Dagger', summary: 'A dagger that devours light within 5 feet, granting advantage on stealth checks in darkness.', rarity: 'Uncommon', attunement: true, description: '**Voidfang Dagger**\n*Weapon (dagger), uncommon (requires attunement)*\n\nThis dagger is forged from a metal that absorbs light. While you hold it, nonmagical light within 5 feet of you is extinguished.\n\n**Shadow Strike.** While in dim light or darkness, you have advantage on the first attack roll you make each turn with this weapon.\n\n**Cloak of Night.** While holding this dagger, you have advantage on Dexterity (Stealth) checks made in dim light or darkness.\n\n**Curse.** This dagger craves darkness. If you are in bright light for more than 1 hour while attuned, you take 1d4 psychic damage at the start of each subsequent turn until you enter dim light or darkness.\n\n*The blade seems to drink the torchlight, leaving a pocket of shadow that clings to your hand like silk.*', tags: ['dagger', 'stealth', 'darkness', 'cursed'], art: 'dark fantasy oil painting of a black dagger that absorbs surrounding light, dramatic lighting, tabletop RPG item art, no text' },
  { title: 'Stormcaller\'s Gauntlet', summary: 'A gauntlet that lets you hurl bolts of lightning once per day and grants resistance to lightning damage.', rarity: 'Rare', attunement: true, description: '**Stormcaller\'s Gauntlet**\n*Wondrous item, rare (requires attunement)*\n\nThis iron gauntlet crackles with static electricity. While wearing it, you have resistance to lightning damage.\n\n**Lightning Bolt (1/day).** As an action, you can cast Lightning Bolt (save DC 15) from the gauntlet. When you do, the gauntlet becomes inert until the next dawn.\n\n**Static Grip.** You have advantage on checks to grapple or climb metal surfaces.\n\n**Thunderclap.** As a bonus action, you can clap the gauntleted hand against your other palm to cast Thunderclap (save DC 13).\n\n*The gauntlet hums with the fury of a caged storm. Those who wear it say they can taste ozone.*', tags: ['gauntlet', 'lightning', 'combat'], art: 'dark fantasy oil painting of an iron gauntlet crackling with lightning energy, dramatic lighting, tabletop RPG item art, no text' },
  { title: 'Hearthstone Pendant', summary: 'A warm stone pendant that creates a 20-foot sphere of comfortable temperature and wards off cold damage.', rarity: 'Common', attunement: false, description: '**Hearthstone Pendant**\n*Wondrous item, common*\n\nThis smooth, palm-sized stone is always warm to the touch. While wearing it, you and all creatures within 20 feet of you are comfortable in temperatures as cold as -50 degrees Fahrenheit.\n\n**Hearthward.** As a reaction when you take cold damage, you can reduce that damage by 1d8. You can use this property three times, regaining all uses at dawn.\n\n**Campfire.** As an action, you can place the pendant on the ground to create a campfire-like warmth and dim light in a 20-foot radius for 8 hours. The pendant cannot be used for Hearthward while placed this way.\n\n*It smells faintly of woodsmoke and feels like holding a cup of tea.*', tags: ['pendant', 'survival', 'cold', 'utility'], art: 'dark fantasy oil painting of a glowing warm orange stone pendant on a leather cord, dramatic lighting, tabletop RPG item art, no text' },
  { title: 'Mask of the Mirrored Self', summary: 'A silver mask that lets you assume the appearance of the last creature you touched, once per long rest.', rarity: 'Rare', attunement: true, description: '**Mask of the Mirrored Self**\n*Wondrous item, rare (requires attunement)*\n\nThis featureless silver mask has no eyeholes — when worn, it becomes transparent from the inside.\n\n**Mirror Image (1/long rest).** As an action, you assume the appearance of the last humanoid you touched with your bare hand. The disguise lasts for 1 hour and includes voice, clothing, and mannerisms you observed. A creature can see through the disguise with a successful DC 16 Investigation check.\n\n**True Sight Immunity.** The disguise is not an illusion — it physically reshapes the mask and your features. It is not affected by True Seeing or Dispel Magic.\n\n**Fracture.** If you take 20 or more damage in a single hit while disguised, the mask cracks and the disguise ends immediately.\n\n*When you put it on, the silver flows like mercury across your face. When you take it off, your reflection lingers a moment too long.*', tags: ['mask', 'disguise', 'infiltration'], art: 'dark fantasy oil painting of a featureless silver mask reflecting a different face, dramatic lighting, tabletop RPG item art, no text' },
  { title: 'The Glutton\'s Fork', summary: 'A cursed dining fork that makes any food delicious but slowly increases your appetite until nothing satisfies.', rarity: 'Uncommon', attunement: true, description: '**The Glutton\'s Fork**\n*Wondrous item, uncommon (requires attunement, cursed)*\n\nThis ornate silver fork has tiny ruby eyes set into its handle. Food eaten with this fork tastes extraordinary — the best version of itself.\n\n**Exquisite Taste.** Any food eaten with this fork provides double the normal nourishment and grants 1d4 temporary hit points (lasting 1 hour).\n\n**Curse: The Hunger.** After attuning, you must eat twice the normal amount of food each day or gain one level of exhaustion. After a week, three times. After a month, four times. The hunger never stops growing. The fork cannot be unattuned by normal means — only Remove Curse or destroying the fork ends it.\n\n*It was a gift from a hag. It is always a gift from a hag.*', tags: ['cursed', 'food', 'fork', 'hag'], art: 'dark fantasy oil painting of an ornate silver fork with tiny ruby eyes on the handle surrounded by decadent food, dramatic lighting, no text' },
  { title: 'Ironwood Bulwark', summary: 'A living wooden shield that regenerates damage overnight and can grow roots to anchor you in place.', rarity: 'Uncommon', attunement: false, description: '**Ironwood Bulwark**\n*Armor (shield), uncommon*\n\nThis round shield is carved from living ironwood — it still has bark and tiny leaves that change with the seasons. It grants +2 AC as a normal shield.\n\n**Living Shield.** If the shield takes damage from an attack, it regrows the damage overnight. It has 20 HP and AC 15. If reduced to 0 HP, it must be planted in soil and watered daily for a week to regrow.\n\n**Root Anchor (1/day).** As a bonus action, you can plant the shield\'s edge in the ground. Roots extend, giving you advantage on Strength checks and saving throws against being moved or knocked prone for 1 minute. You cannot move while anchored. You can uproot as a bonus action.\n\n*In spring, it blooms. In winter, the bark hardens to iron.*', tags: ['shield', 'druid', 'nature', 'defense'], art: 'dark fantasy oil painting of a round wooden shield with living bark and small leaves growing from it, dramatic lighting, no text' },
  { title: 'Songblade Rapier', summary: 'A rapier that hums a note on each hit, building to a crescendo that deals thunder damage in a cone.', rarity: 'Rare', attunement: true, description: '**Songblade Rapier**\n*Weapon (rapier), rare (requires attunement by a bard or fighter)*\n\n+1 rapier. Each time you hit a creature with this weapon, the blade emits a musical note, rising in pitch.\n\n**Crescendo.** After landing 3 hits in a single combat (they don\'t need to be consecutive), you can use a bonus action to release the stored sound. Each creature in a 15-foot cone must make a DC 14 Constitution saving throw, taking 3d8 thunder damage on a failure, or half on a success. The count resets to 0.\n\n**Perfect Pitch.** While attuned, you have advantage on Performance checks involving singing or music.\n\n*The first note is a whisper. The second, a hum. The third is a warning. The fourth is too late.*', tags: ['rapier', 'bard', 'thunder', 'music'], art: 'dark fantasy oil painting of a silver rapier emanating visible musical sound waves, dramatic lighting, tabletop RPG item art, no text' },
  { title: 'Lantern of Lost Souls', summary: 'A lantern that reveals invisible creatures and can trap the essence of a defeated undead.', rarity: 'Rare', attunement: true, description: '**Lantern of Lost Souls**\n*Wondrous item, rare (requires attunement)*\n\nThis iron lantern burns with blue-white flame that never needs fuel.\n\n**Soullight.** The lantern sheds bright light in a 30-foot radius and dim light for another 30 feet. Invisible creatures within the bright light become visible as pale outlines.\n\n**Soul Trap (3 charges).** When you reduce an undead creature to 0 HP within the lantern\'s bright light, you can use a reaction and 1 charge to trap its essence. While trapped, the undead cannot reform or be raised. The lantern can hold up to 3 souls. As an action, you can release a trapped soul to cast Speak with Dead (no components) on it, then the soul passes on. The lantern regains 1 charge at dawn.\n\n*The flame flickers with faces — brief, sorrowful, grateful.*', tags: ['lantern', 'undead', 'cleric', 'light'], art: 'dark fantasy oil painting of an iron lantern with blue-white flame and ghostly faces in the light, dramatic lighting, no text' },
  { title: 'Cinderheart Amulet', summary: 'An amulet that absorbs fire damage and can release it as a blast, but burns hotter the more it stores.', rarity: 'Rare', attunement: true, description: '**Cinderheart Amulet**\n*Wondrous item, rare (requires attunement)*\n\nA blackened iron heart on a chain, warm to the touch.\n\n**Absorb Flame.** When you take fire damage, you can use your reaction to reduce it by 2d6. The absorbed fire is stored in the amulet (max 30 points). While the amulet stores fire, it glows and you have resistance to cold damage.\n\n**Cinder Blast.** As an action, release all stored fire in a 20-foot cone. Each creature makes a DC 14 Dex save, taking the stored amount as fire damage on a failure, half on success.\n\n**Overload.** If the stored fire exceeds 30, the amulet cracks and deals 6d6 fire damage to you (no save). It reforms at dawn.\n\n*It beats. Not like a heart — like a furnace.*', tags: ['amulet', 'fire', 'absorption', 'blast'], art: 'dark fantasy oil painting of a blackened iron heart amulet glowing with internal fire on a chain, dramatic lighting, no text' },
  { title: 'Gossamer Cloak', summary: 'A fey-spun cloak that grants advantage on saves vs. charm and lets you turn ethereal for 6 seconds once per day.', rarity: 'Uncommon', attunement: true, description: '**Gossamer Cloak**\n*Wondrous item, uncommon (requires attunement)*\n\nThis cloak is woven from spider silk and moonlight. It weighs almost nothing and shimmers faintly.\n\n**Fey Ward.** You have advantage on saving throws against being charmed.\n\n**Ethereal Step (1/day).** As a bonus action, you become ethereal until the end of your next turn. While ethereal, you can move through creatures and objects as if they were difficult terrain. If you end your turn inside a solid object, you take 1d10 force damage and are shunted to the nearest unoccupied space.\n\n**Moonlit.** In moonlight, the cloak grants +1 to AC.\n\n*It feels like wearing a thought. The fey who made it said it was the last thought before sleep.*', tags: ['cloak', 'fey', 'ethereal', 'charm'], art: 'dark fantasy oil painting of a shimmering translucent cloak woven from moonlight and spider silk, dramatic lighting, no text' },
  { title: 'Bonecaller\'s Horn', summary: 'A carved bone horn that summons 1d4 skeleton warriors for 1 hour, but each use ages the blower by 1 year.', rarity: 'Rare', attunement: false, description: '**Bonecaller\'s Horn**\n*Wondrous item, rare*\n\nA horn carved from the thighbone of an ancient giant, etched with necromantic runes.\n\n**Raise the Dead (1/day).** As an action, blow the horn. 1d4 skeletons rise from the nearest ground within 30 feet. They obey your verbal commands for 1 hour, then collapse to dust. The skeletons use the standard Skeleton stat block.\n\n**Price of Command.** Each time you blow the horn, you age 1 year. This aging is real and cannot be reversed by anything short of a Wish spell.\n\n**Last Breath.** If you blow the horn while at 0 HP (before death saves), you summon 2d4 skeletons and stabilize at 1 HP. You age 10 years.\n\n*The sound is not a note. It is the creak of a coffin lid.*', tags: ['horn', 'necromancy', 'skeletons', 'cost'], art: 'dark fantasy oil painting of a large bone horn with necromantic runes and skeletal hands reaching from the ground, dramatic lighting, no text' },
  { title: 'The Diplomat\'s Quill', summary: 'A magic quill that translates any written text and can forge any signature perfectly.', rarity: 'Uncommon', attunement: true, description: '**The Diplomat\'s Quill**\n*Wondrous item, uncommon (requires attunement)*\n\nThis elegant quill is tipped with phoenix feather and writes in ink that shifts color.\n\n**Translator.** While holding the quill, you can read any written language. The quill translates the text as you trace it.\n\n**Perfect Forgery.** If you have seen a creature\'s handwriting, you can perfectly replicate it. The forgery is indistinguishable from the original without magic (DC 20 Investigation to spot without magical aid).\n\n**Diplomatic Seal.** Documents signed with this quill radiate a faint aura of truthfulness. Creatures who read them make Insight checks with disadvantage to determine if the content is false.\n\n*The ink is the color of whatever the reader most trusts.*', tags: ['quill', 'forgery', 'translation', 'social'], art: 'dark fantasy oil painting of an elegant feather quill writing in color-shifting magical ink on parchment, dramatic lighting, no text' },
  { title: 'Ironhide Bracers', summary: 'Bracers that grant +1 AC and can harden to stone once per day, granting resistance to all physical damage for 1 round.', rarity: 'Uncommon', attunement: true, description: '**Ironhide Bracers**\n*Wondrous item, uncommon (requires attunement)*\n\nThese dull iron bracers are etched with protective runes.\n\n**Iron Guard.** While wearing these bracers and not using a shield, you gain a +1 bonus to AC.\n\n**Stonehide (1/day).** As a reaction when you are hit by an attack, your skin hardens to grey stone until the start of your next turn. You have resistance to bludgeoning, piercing, and slashing damage for the duration. Your speed is reduced to 0 during this time.\n\n*The runes glow when danger is near. By the time you see them, it\'s too late to run — so you stand.*', tags: ['bracers', 'defense', 'AC', 'tank'], art: 'dark fantasy oil painting of iron bracers with glowing protective runes on a warrior forearm, dramatic lighting, no text' },
  { title: 'Wraith Chain', summary: 'A cursed chain whip that deals necrotic damage and heals the wielder, but whispers dark commands.', rarity: 'Rare', attunement: true, description: '**Wraith Chain**\n*Weapon (whip), rare (requires attunement, cursed)*\n\n+1 whip. This weapon deals an additional 1d4 necrotic damage on a hit. When you deal necrotic damage with this weapon, you regain hit points equal to the necrotic damage dealt.\n\n**Curse: Voice of the Chain.** The chain whispers to you during combat, urging you to attack downed enemies, fleeing foes, and eventually allies. After each combat, make a DC 12 Wisdom save or be compelled to attack the nearest living creature on your next turn.\n\n**Breaking the Curse.** Remove Curse suppresses the whispers for 1d4 days. Destroying the chain permanently requires submerging it in holy water for 24 hours.\n\n*It wraps around your wrist like it belongs there. After a week, you agree.*', tags: ['whip', 'necrotic', 'cursed', 'vampire'], art: 'dark fantasy oil painting of a spectral chain whip dripping with dark energy coiled around an arm, dramatic lighting, no text' },
  { title: 'Prism Lens', summary: 'A monocle that reveals illusions, hidden doors, and magical auras within 30 feet.', rarity: 'Uncommon', attunement: true, description: '**Prism Lens**\n*Wondrous item, uncommon (requires attunement)*\n\nThis crystal monocle refracts light into tiny rainbows.\n\n**True Sight (limited).** While wearing the lens, you can see through illusions, see invisible creatures, and detect magical auras within 30 feet. This does not extend to the Ethereal Plane.\n\n**Hidden Ways.** Secret doors and concealed mechanisms within 30 feet are outlined in faint prismatic light.\n\n**Fragile.** The lens has AC 10 and 1 HP. If destroyed, it reforms at the next dawn in the pocket of whoever last wore it.\n\n*The world seen through it is more beautiful and more terrible than the world without it.*', tags: ['monocle', 'detection', 'illusion', 'investigation'], art: 'dark fantasy oil painting of a crystal monocle refracting rainbow light revealing hidden magical symbols, dramatic lighting, no text' },
  { title: 'Umbral Bow', summary: 'A bow that fires arrows of solidified shadow. The arrows ignore half cover and dim light within 60 feet.', rarity: 'Rare', attunement: true, description: '**Umbral Bow**\n*Weapon (shortbow or longbow), rare (requires attunement)*\n\n+1 bow. This bow does not require ammunition — it creates arrows from your shadow.\n\n**Shadow Arrows.** Arrows fired from this bow are made of solidified shadow. They deal normal weapon damage plus 1d4 necrotic. These arrows ignore half cover and three-quarters cover.\n\n**Dusk Sight.** While attuned, you have darkvision out to 60 feet.\n\n**Shadow Cost.** For each arrow you fire, your shadow shrinks slightly. After firing 20 arrows in a day, your shadow disappears entirely until dawn. While shadowless, you have disadvantage on Charisma checks as people find your appearance unsettling.\n\n*It draws from you. Not blood — something dimmer.*', tags: ['bow', 'shadow', 'necrotic', 'ranger'], art: 'dark fantasy oil painting of a dark bow firing arrows made of solidified shadow, dramatic lighting, no text' },
  { title: 'Runesmith\'s Hammer', summary: 'A warhammer that can inscribe temporary runes on objects, granting them +1 AC or +1 damage for 1 hour.', rarity: 'Uncommon', attunement: true, description: '**Runesmith\'s Hammer**\n*Weapon (warhammer), uncommon (requires attunement)*\n\n+1 warhammer. The head is inscribed with shifting dwarven runes.\n\n**Inscribe Rune (3/day).** As an action, touch a weapon or piece of armor with the hammer. Choose one:\n- **Rune of Might:** The weapon gains +1 to damage rolls for 1 hour.\n- **Rune of Warding:** The armor grants +1 AC for 1 hour.\n\nOnly one rune can be active on an item at a time. The runes fade to dim letters after the duration.\n\n**Dwarvish Command.** While attuned, you can read and speak Dwarvish.\n\n*Every strike writes a promise in the steel.*', tags: ['hammer', 'runes', 'dwarven', 'buff'], art: 'dark fantasy oil painting of a dwarven warhammer with glowing shifting runes on its head, dramatic forge lighting, no text' },
  { title: 'Serpent\'s Tongue Ring', summary: 'A ring shaped like a coiled serpent that lets you speak with snakes and grants immunity to poison for 1 hour per day.', rarity: 'Uncommon', attunement: true, description: '**Serpent\'s Tongue Ring**\n*Wondrous item, uncommon (requires attunement)*\n\nA ring shaped like a serpent eating its own tail, with emerald eyes.\n\n**Serpent Speech.** While wearing the ring, you can speak with and understand snakes.\n\n**Venom Ward (1/day).** As an action, you gain immunity to poison damage and the poisoned condition for 1 hour.\n\n**Venom Strike.** Once per long rest, as a bonus action, you can coat one weapon in magical venom. The next hit with that weapon deals an additional 1d6 poison damage, and the target must succeed on a DC 13 Constitution save or be poisoned for 1 minute.\n\n*The emerald eyes blink when it hears a lie.*', tags: ['ring', 'poison', 'snake', 'immunity'], art: 'dark fantasy oil painting of a golden ring shaped like a serpent with emerald eyes coiled on a finger, dramatic lighting, no text' },
  { title: 'Chrono Compass', summary: 'A compass that points toward the nearest temporal anomaly and can slow time in a 10-foot radius for 1 round.', rarity: 'Very Rare', attunement: true, description: '**Chrono Compass**\n*Wondrous item, very rare (requires attunement)*\n\nThis brass pocket compass has 13 hands, each spinning at different speeds.\n\n**Temporal Sense.** The compass needle points toward the nearest temporal anomaly within 1 mile (time loops, stasis fields, chronomancy residue).\n\n**Slow Field (1/day).** As an action, create a 10-foot radius sphere of slowed time centered on you. Until the start of your next turn, all creatures other than you in the sphere have their speed halved and cannot take reactions. Attack rolls against them have advantage.\n\n**Paradox Resistance.** You have advantage on saving throws against effects that would age you, slow you, or alter your personal timeline.\n\n*Twelve hands tell you the time. The thirteenth tells you when.*', tags: ['compass', 'time', 'slow', 'rare'], art: 'dark fantasy oil painting of a brass compass with multiple spinning hands surrounded by temporal distortion, dramatic lighting, no text' },
  { title: 'Pilgrim\'s Staff', summary: 'A walking staff that heals 2d8 HP once per day and creates a protective shelter overnight.', rarity: 'Uncommon', attunement: true, description: '**Pilgrim\'s Staff**\n*Staff, uncommon (requires attunement by a cleric, druid, or monk)*\n\nA simple wooden walking staff with a crystal at its head that glows softly.\n\n**Healing Touch (1/day).** As an action, touch a creature to restore 2d8 + your Wisdom modifier hit points.\n\n**Pilgrim\'s Shelter (1/day).** Plant the staff in the ground to create an invisible dome of force (10-foot radius) that lasts until dawn. The interior is dry, warm, and soundproofed. Creatures inside can see out; creatures outside cannot see in. The dome has AC 15 and 50 HP.\n\n**Way Finder.** The crystal glows brighter as you approach consecrated ground.\n\n*It has been carried by a thousand pilgrims. Each left a prayer in the wood.*', tags: ['staff', 'healing', 'shelter', 'cleric'], art: 'dark fantasy oil painting of a simple wooden staff with a glowing crystal head planted in the ground creating a dome of light, dramatic lighting, no text' },
  { title: 'The Jester\'s Coin', summary: 'A two-headed coin that forces any creature to accept a wager — but the stakes are always higher than expected.', rarity: 'Uncommon', attunement: false, description: '**The Jester\'s Coin**\n*Wondrous item, uncommon*\n\nA gold coin with a laughing face on both sides. It always feels slightly warm.\n\n**Compel Wager (1/day).** Show the coin to a creature that can see it. That creature must make a DC 14 Wisdom save or agree to a simple wager of your proposal (a game, a bet, a contest). The wager must be something the creature could reasonably agree to. On a success, the creature is immune to this effect for 24 hours.\n\n**Double or Nothing.** The coin magically enforces wagers. If the loser tries to renege, they take 2d6 psychic damage each day until they pay. If you try to cheat, you take the same.\n\n**Cursed Memory.** The coin always finds its way back to you. Even if you give it away, it appears in your pocket within 1d4 days.\n\n*You can\'t lose. That\'s the problem — neither can the coin.*', tags: ['coin', 'gambling', 'social', 'cursed'], art: 'dark fantasy oil painting of a golden coin with a laughing jester face on both sides surrounded by magical sparks, dramatic lighting, no text' },
  { title: 'Aegis of the Oath', summary: 'A paladin\'s shield that strengthens with conviction — +1 normally, +2 when protecting an innocent, +3 when fulfilling a sworn oath.', rarity: 'Rare', attunement: true, description: '**Aegis of the Oath**\n*Armor (shield), rare (requires attunement by a paladin)*\n\nThis plain steel shield bears no emblem until attuned. Then it displays the symbol of your oath.\n\n**Scaling Protection.**\n- Normally: +1 bonus to AC (in addition to the shield\'s base +2).\n- When an innocent creature is within 5 feet: +2 bonus instead.\n- When you are actively fulfilling a sworn oath (DM\'s discretion): +3 bonus instead.\n\n**Oath Sense.** The shield grows warm when an innocent is in danger within 60 feet.\n\n**Broken Oath.** If you willingly break a sworn oath while attuned, the shield shatters. It can be reforged only by a celestial.\n\n*It knows what you promised. It holds you to it.*', tags: ['shield', 'paladin', 'oath', 'scaling'], art: 'dark fantasy oil painting of a steel shield with a glowing oath symbol surrounded by divine light, dramatic lighting, no text' },
  { title: 'Spore Satchel', summary: 'A druid\'s pouch that grows 3 types of magical mushrooms daily: healing, poison, and light.', rarity: 'Uncommon', attunement: true, description: '**Spore Satchel**\n*Wondrous item, uncommon (requires attunement by a druid or ranger)*\n\nA leather pouch lined with damp moss. Each dawn, it grows 3 mushrooms (one of each type):\n\n**Mend Cap (red).** Eating one heals 1d6+2 HP. Tastes like warm bread.\n\n**Venom Gill (purple).** Can be crushed and applied to a weapon as an action. The next hit deals 1d8 extra poison damage. Spoils after 24 hours.\n\n**Glow Spore (blue).** Crush and throw (20 feet). Creates bright light in a 15-foot radius for 1 hour. Sticks to surfaces.\n\nMushrooms spoil at the next dawn if not used. The satchel must be kept damp.\n\n*It smells like a forest floor after rain. The mushrooms hum if you listen closely.*', tags: ['pouch', 'druid', 'mushrooms', 'utility'], art: 'dark fantasy oil painting of a leather satchel with glowing magical mushrooms growing from damp moss inside, dramatic lighting, no text' },
  { title: 'The Final Word', summary: 'A book that records the last words of anyone who dies within 100 feet. Contains centuries of dying whispers.', rarity: 'Rare', attunement: true, description: '**The Final Word**\n*Wondrous item, rare (requires attunement)*\n\nThis leather-bound book is always full — the pages contain the last words of every creature that has died within 100 feet of it. Entries appear in the creature\'s own language.\n\n**Record.** When a creature dies within 100 feet, its last words (or last thought, if it cannot speak) appear on the next blank page. The book creates new pages as needed.\n\n**Consult the Dead (1/day).** As an action, read an entry aloud. The dead creature\'s voice speaks through the book for 1 minute, answering up to 3 questions as though under Speak with Dead.\n\n**Weight of Words.** The book gets physically heavier with each recorded death. After 100 entries, it weighs 20 pounds. After 1000, it weighs 100 pounds. The current book contains 847 entries.\n\n*The first entry is illegible — older than the language it was written in. The most recent one is still wet.*', tags: ['book', 'death', 'knowledge', 'necromancy'], art: 'dark fantasy oil painting of an ancient leather-bound book with ghostly whispered words floating from its pages, dramatic lighting, no text' },
];

MAGIC_ITEMS.forEach(m => {
  ITEMS.push({
    kind: 'magic_item',
    title: m.title,
    summary: m.summary,
    description: m.description,
    tags: m.tags,
    art_prompt: m.art,
    price_cents: 0,
    edition: '5e-2024',
    origin: 'original',
    license: 'cc-by-4.0',
  });
});

// ---- 20 Boss Monsters ----
const MONSTERS = [
  { title: 'The Ashwalker', summary: 'CR 5 fire elemental that leaves trails of choking ash. Immune to fire, vulnerable to cold. Legendary actions.', tags: ['fire', 'elemental', 'boss', 'ash'], description: '**The Ashwalker**\n*Large Elemental, Neutral Evil*\n\n**Armor Class** 15 (natural armor)\n**Hit Points** 102 (12d10 + 36)\n**Speed** 40 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 16 (+3) | 14 (+2) | 16 (+3) | 8 (-1) | 12 (+1) | 10 (+0) |\n\n**Damage Immunities** fire, poison\n**Damage Vulnerabilities** cold\n**Condition Immunities** poisoned, exhaustion\n**Senses** darkvision 60 ft., passive Perception 11\n**Languages** Ignan\n**Challenge** 5 (1,800 XP)\n\n**Ash Trail.** The Ashwalker leaves a 5-foot-wide trail of choking ash wherever it moves. Creatures that start their turn in the ash must make a DC 13 Constitution save or be blinded until the end of their turn. The ash dissipates after 1 minute.\n\n**Fire Form.** The Ashwalker can move through a space as narrow as 1 inch. A creature that touches it or hits it with a melee attack within 5 feet takes 5 (1d10) fire damage.\n\n**Actions**\n\n**Multiattack.** The Ashwalker makes two Cinder Slam attacks.\n\n**Cinder Slam.** *Melee Weapon Attack:* +6 to hit, reach 10 ft., one target. *Hit:* 10 (2d6 + 3) bludgeoning damage plus 7 (2d6) fire damage.\n\n**Ash Storm (Recharge 5-6).** The Ashwalker erupts, filling a 20-foot radius with burning ash. Each creature in the area must make a DC 13 Dexterity save, taking 21 (6d6) fire damage on a failure, or half on a success. The area is heavily obscured for 1 round.\n\n**Legendary Actions (2/round)**\n\n**Cinder Step.** The Ashwalker moves up to 20 feet without provoking opportunity attacks.\n**Flare (Costs 2 Actions).** Each creature within 10 feet must make a DC 13 Con save or take 10 (3d6) fire damage.\n\n**Tactical Notes:** The Ashwalker uses its ash trail to divide the party, forcing ranged attackers to reposition through blinding ash while it focuses melee fighters. Cold damage stops its trail for 1 round.\n\n**Lore:** Born from a forest fire that burned for a year without rain, the Ashwalker wanders seeking fuel. It doesn\'t hate — it hungers.', art: 'dark fantasy oil painting of a massive humanoid figure made of smoldering ash and ember with glowing core, dramatic lighting, no text' },
  { title: 'The Broodmother', summary: 'CR 7 aberration that spawns smaller creatures from its body. Each spawn weakens the mother but gains her abilities.', tags: ['aberration', 'boss', 'swarm', 'spawn'], description: '**The Broodmother**\n*Huge Aberration, Chaotic Evil*\n\n**AC** 14 (natural armor) **HP** 136 (16d12 + 32) **Speed** 30 ft., climb 30 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 18 (+4) | 10 (+0) | 14 (+2) | 6 (-2) | 14 (+2) | 4 (-3) |\n\n**Damage Resistances** bludgeoning\n**Condition Immunities** frightened, prone\n**Senses** blindsight 60 ft., passive Perception 12\n**Challenge** 7 (2,900 XP)\n\n**Broodspawn.** At the start of each of the Broodmother\'s turns, she spawns 1 Broodling (see below) in an unoccupied space within 5 feet. Each spawn reduces her max HP by 10. When her max HP reaches 0, she dies.\n\n**Actions**\n\n**Multiattack.** Two tentacle attacks.\n**Tentacle.** +7 to hit, reach 15 ft. *Hit:* 13 (2d8 + 4) bludgeoning + 4 (1d8) acid.\n**Acid Spray (Recharge 5-6).** 30 ft. cone, DC 14 Dex, 28 (8d6) acid damage, half on save.\n\n**Broodling (CR 1/4)**\nSmall aberration, AC 11, HP 11, Speed 40 ft. Bite: +3 to hit, 4 (1d6+1) piercing. If the Broodmother is bloodied, all Broodlings gain +2 to attack and damage.\n\n**Tactical Notes:** Kill the Broodmother fast or be overwhelmed. Each round she lives adds another creature to the battlefield. Area damage that hits both mother and spawn is optimal.', art: 'dark fantasy oil painting of a massive aberrant creature spawning smaller versions of itself from its body, dramatic lighting, no text' },
  { title: 'Wraithwood Stag', summary: 'CR 4 undead beast. Its antlers drain life on hit. When killed, it splits into two Wraithwood Does.', tags: ['undead', 'beast', 'stag', 'forest'], description: '**Wraithwood Stag**\n*Large Undead Beast, Neutral Evil*\n\n**AC** 14 **HP** 85 (10d10 + 30) **Speed** 50 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 16 (+3) | 18 (+4) | 16 (+3) | 4 (-3) | 14 (+2) | 8 (-1) |\n\n**Damage Immunities** poison, necrotic\n**Condition Immunities** poisoned, exhaustion, charmed\n**Senses** darkvision 120 ft.\n**Challenge** 4 (1,100 XP)\n\n**Life Drain Antlers.** On a hit with its gore attack, the target\'s HP maximum is reduced by the necrotic damage dealt. This lasts until the target finishes a long rest.\n\n**Death Split.** When reduced to 0 HP, the stag splits into 2 Wraithwood Does (CR 1 each, HP 22, same immunities, bite attack +4, 1d6+2 piercing + 1d4 necrotic).\n\n**Actions**\n\n**Multiattack.** Gore + Hooves.\n**Gore.** +6 to hit, reach 10 ft. *Hit:* 11 (2d6 + 4) piercing + 7 (2d6) necrotic.\n**Hooves.** +6 to hit. *Hit:* 9 (2d4 + 4) bludgeoning. Target must DC 14 Str save or be knocked prone.\n\n**Lore:** Wraithwood Stags are deer corrupted by necrotic ley lines. They appear majestic from afar — antlers glowing with pale light — until they charge.', art: 'dark fantasy oil painting of an undead stag with glowing ghostly antlers in a dark forest, dramatic moonlight, no text' },
  { title: 'The Cogwright', summary: 'CR 6 construct boss that repairs itself each round and can reconfigure its body between melee and ranged forms.', tags: ['construct', 'boss', 'clockwork', 'adaptive'], description: '**The Cogwright**\n*Large Construct, Unaligned*\n\n**AC** 17 (natural armor) **HP** 115 (11d10 + 55) **Speed** 30 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 20 (+5) | 12 (+1) | 20 (+5) | 10 (+0) | 10 (+0) | 1 (-5) |\n\n**Damage Immunities** poison, psychic\n**Condition Immunities** charmed, exhaustion, frightened, paralyzed, petrified, poisoned\n**Challenge** 6 (2,300 XP)\n\n**Self-Repair.** At the start of its turn, the Cogwright regains 10 HP if it has at least 1 HP.\n\n**Reconfigure (Bonus Action).** The Cogwright shifts between two forms:\n- **Siege Form:** +2 to attack rolls, ranged slam (60 ft.), speed 20 ft.\n- **Assault Form:** +2 to damage, reach 15 ft., speed 40 ft.\n\n**Actions**\n\n**Multiattack.** Two slam attacks.\n**Slam.** +8 to hit, reach 10 ft. (or 60 ft. in Siege Form). *Hit:* 14 (2d8 + 5) bludgeoning.\n**Gear Storm (Recharge 6).** 20 ft. radius, 60 ft. range. DC 15 Dex, 28 (8d6) slashing, half on save.\n\n**Tactical Notes:** Destroying its repair core (AC 20, 30 HP, inside its torso) stops Self-Repair. Players need to grapple or restrain it first.', art: 'dark fantasy oil painting of a massive clockwork construct with shifting gears reconfiguring its body, dramatic lighting, no text' },
  { title: 'Mireborn Hydra', summary: 'CR 8 plant/beast hybrid. Each head regrows as a different element (fire, ice, acid, lightning). 4 heads.', tags: ['hydra', 'plant', 'elemental', 'boss'], description: '**Mireborn Hydra**\n*Huge Plant (Beast), Unaligned*\n\n**AC** 15 (natural bark) **HP** 157 (15d12 + 60) **Speed** 30 ft., swim 30 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 20 (+5) | 10 (+0) | 18 (+4) | 2 (-4) | 10 (+0) | 4 (-3) |\n\n**Challenge** 8 (3,900 XP)\n\n**Four Heads.** The hydra starts with 4 heads, each with a different element:\n- **Fire Head:** Breath 15 ft. cone, 2d6 fire, DC 14 Dex.\n- **Frost Head:** Breath 15 ft. cone, 2d6 cold, DC 14 Con.\n- **Acid Head:** Breath 15 ft. line, 2d6 acid, DC 14 Dex.\n- **Storm Head:** Breath 15 ft. line, 2d6 lightning, DC 14 Con.\n\n**Reactive Heads.** For each head beyond one, the hydra gets an extra reaction (one breath per head per round).\n\n**Regrowth.** If a head is severed (25+ damage in one hit), it regrows at the start of the hydra\'s next turn as a random element (d4). Fire damage to the stump prevents regrowth.\n\n**Actions**\n\n**Multiattack.** One bite per head.\n**Bite.** +8 to hit, reach 10 ft. *Hit:* 10 (1d10 + 5) piercing + 3 (1d6) elemental (matching head).\n\n**Lore:** Grown where four elemental ley lines intersect in a swamp, this creature is as much a force of nature as a beast.', art: 'dark fantasy oil painting of a four-headed hydra made of twisted vines and bark with elemental energy in each head, dramatic lighting, no text' },
  { title: 'The Threadweaver', summary: 'CR 5 fey spider that weaves illusions into its web. Victims don\'t realize they\'re trapped until it\'s too late.', tags: ['fey', 'spider', 'illusion', 'boss'], description: '**The Threadweaver**\n*Large Fey, Chaotic Neutral*\n\n**AC** 14 **HP** 90 (12d10 + 24) **Speed** 40 ft., climb 40 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 14 (+2) | 18 (+4) | 14 (+2) | 16 (+3) | 14 (+2) | 16 (+3) |\n\n**Challenge** 5 (1,800 XP)\n\n**Illusory Web.** The Threadweaver\'s webs are invisible and project illusory terrain. A creature entering its web sees the terrain it expects (a path, a room) and must make a DC 14 Wisdom save to notice the web. On failure, they are restrained and don\'t realize it for 1 round.\n\n**Actions**\n\n**Multiattack.** Bite + Web Snare.\n**Bite.** +7 to hit. *Hit:* 9 (1d10 + 4) piercing + 7 (2d6) poison. DC 13 Con or poisoned for 1 minute.\n**Web Snare.** 30 ft. range. DC 14 Dex or restrained. The web is invisible.\n**Phantasmal Lure (Recharge 5-6).** One creature within 60 ft. must DC 14 Wis save or use its reaction to move 30 ft. toward the Threadweaver by the shortest route.\n\n**Lore:** The Threadweaver is not malicious — it\'s an artist. Its webs are beautiful. Its victims are the medium.', art: 'dark fantasy oil painting of a beautiful fey spider weaving shimmering illusions into invisible webs, dramatic lighting, no text' },
  { title: 'Ironjaw Rex', summary: 'CR 9 dinosaur/construct hybrid. Metal-plated jaws crush through any armor. Siege monster with a terrifying charge.', tags: ['dinosaur', 'construct', 'siege', 'boss'], description: '**Ironjaw Rex**\n*Huge Construct (Beast), Unaligned*\n\n**AC** 18 (metal plating) **HP** 168 (16d12 + 64) **Speed** 50 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 22 (+6) | 10 (+0) | 18 (+4) | 2 (-4) | 12 (+1) | 6 (-2) |\n\n**Challenge** 9 (5,000 XP)\n\n**Siege Monster.** Deals double damage to objects and structures.\n\n**Ironjaw.** The Rex\'s bite ignores resistance to bludgeoning, piercing, and slashing damage.\n\n**Thundering Charge.** If the Rex moves at least 30 ft. straight toward a target, the target must DC 16 Str save or be knocked prone and take an extra 14 (4d6) bludgeoning.\n\n**Actions**\n\n**Multiattack.** Bite + Tail.\n**Bite.** +10 to hit, reach 10 ft. *Hit:* 25 (3d12 + 6) piercing. If the target is Medium or smaller, it is grappled (escape DC 16). While grappled, the Rex can\'t bite another target.\n**Tail.** +10 to hit, reach 15 ft. *Hit:* 17 (2d10 + 6) bludgeoning.\n\n**Legendary Actions (2/round)**\n\n**Move.** Move up to half speed.\n**Roar (Costs 2).** Each creature within 30 ft. must DC 14 Wis save or be frightened until end of its next turn.\n\n**Lore:** A war-mage\'s greatest (and final) experiment — grafting adamantine plates onto a living predator.', art: 'dark fantasy oil painting of a massive dinosaur with metal-plated jaws and armor plating charging forward, dramatic lighting, no text' },
  { title: 'The Hollow King', summary: 'CR 7 undead sovereign. His crown controls all undead within 300 feet. Destroying the crown ends his power.', tags: ['undead', 'king', 'crown', 'boss'], description: '**The Hollow King**\n*Medium Undead, Lawful Evil*\n\n**AC** 16 (plate, no shield) **HP** 119 (14d8 + 56) **Speed** 30 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 18 (+4) | 12 (+1) | 18 (+4) | 14 (+2) | 16 (+3) | 18 (+4) |\n\n**Damage Immunities** necrotic, poison\n**Challenge** 7 (2,900 XP)\n\n**Crown of Command.** All undead within 300 feet obey the Hollow King\'s verbal commands. Destroying the crown (AC 18, 25 HP, immune to necrotic/poison) causes all commanded undead to collapse.\n\n**Undead Fortitude.** If reduced to 0 HP by non-radiant damage, DC 5 + damage Con save to drop to 1 HP instead.\n\n**Actions**\n\n**Multiattack.** Two Regal Blade attacks.\n**Regal Blade.** +7 to hit. *Hit:* 11 (2d6 + 4) slashing + 7 (2d6) necrotic.\n**Command the Dead (Recharge 5-6).** Up to 6 undead within 300 ft. each take an action immediately (outside their turn).\n**Dread Gaze.** One creature within 30 ft., DC 15 Wis or frightened for 1 minute. Repeat save at end of each turn.\n\n**Legendary Actions (2/round)**\n**Attack.** One Regal Blade attack.\n**Rally (Costs 2).** Each undead within 60 ft. regains 10 HP.', art: 'dark fantasy oil painting of an undead king in rotting royal armor with a glowing crown commanding skeletal soldiers, dramatic lighting, no text' },
  { title: 'Blightmaw Toad', summary: 'CR 3 monstrosity. Huge poisonous toad that swallows whole and exudes toxic gas in a 15-foot aura.', tags: ['monstrosity', 'poison', 'toad', 'swamp'], description: '**Blightmaw Toad**\n*Large Monstrosity, Unaligned*\n\n**AC** 12 **HP** 68 (8d10 + 24) **Speed** 30 ft., swim 40 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 16 (+3) | 10 (+0) | 16 (+3) | 2 (-4) | 10 (+0) | 4 (-3) |\n\n**Challenge** 3 (700 XP)\n\n**Toxic Aura.** Creatures that start their turn within 15 ft. must DC 13 Con save or take 7 (2d6) poison damage and be poisoned until the start of their next turn.\n\n**Amphibious.** Can breathe air and water.\n\n**Actions**\n\n**Bite.** +5 to hit, reach 5 ft. *Hit:* 10 (2d6 + 3) piercing. If Medium or smaller, DC 13 Str or swallowed. Swallowed: blinded, restrained, 7 (2d6) acid damage start of each turn. AC 12, 15 HP from inside to escape.\n**Tongue Lash.** +5 to hit, reach 20 ft. *Hit:* 7 (1d8 + 3) bludgeoning, target is pulled 15 ft. toward the toad.\n\n**Lore:** The Blightmaw Toad is feared not for its bite but its proximity. The gas it exudes kills vegetation for a hundred yards around its lair.', art: 'dark fantasy oil painting of a massive toxic toad in a swamp exuding green poisonous gas, dramatic lighting, no text' },
  { title: 'The Sandglass Sentinel', summary: 'CR 6 construct guardian made of living hourglass sand. Can reverse time for a single creature (undo damage or actions).', tags: ['construct', 'time', 'sand', 'guardian'], description: '**The Sandglass Sentinel**\n*Large Construct, Lawful Neutral*\n\n**AC** 15 **HP** 95 (10d10 + 40) **Speed** 30 ft., fly 10 ft. (hover)\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 16 (+3) | 14 (+2) | 18 (+4) | 12 (+1) | 16 (+3) | 10 (+0) |\n\n**Damage Immunities** poison, psychic\n**Challenge** 6 (2,300 XP)\n\n**Time Reversal (3/day).** As a reaction, the Sentinel reverses time for one creature within 30 feet. Choose one:\n- Undo the last attack that hit the creature (the attack misses instead).\n- Undo the creature\'s last movement (it returns to where it started).\n- Heal the creature for the damage it took last round.\n\n**Sand Form.** The Sentinel can pass through spaces as narrow as 1 inch. It is immune to being grappled.\n\n**Actions**\n\n**Multiattack.** Two Sand Blast attacks.\n**Sand Blast.** +6 to hit, reach 10 ft. *Hit:* 13 (3d6 + 3) bludgeoning.\n**Sandstorm (Recharge 5-6).** 30 ft. radius, DC 14 Con, 21 (6d6) slashing + blinded for 1 round.\n\n**Lore:** Built to guard chronomancers\' vaults, the Sentinel is not aggressive — it only attacks those who try to steal what it guards.', art: 'dark fantasy oil painting of a humanoid figure made of flowing hourglass sand with time symbols floating around it, dramatic lighting, no text' },
  { title: 'Cindermane Lion', summary: 'CR 5 fire beast with a mane of living flame. Its roar ignites the air. Pack alpha that buffs nearby fire creatures.', tags: ['beast', 'fire', 'lion', 'alpha'], description: '**Cindermane Lion**\n*Large Beast (Elemental), Neutral*\n\n**AC** 14 **HP** 95 (10d10 + 40) **Speed** 50 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 18 (+4) | 16 (+3) | 18 (+4) | 6 (-2) | 14 (+2) | 12 (+1) |\n\n**Damage Immunities** fire\n**Challenge** 5 (1,800 XP)\n\n**Flame Mane.** Creatures that hit the lion with a melee attack from within 5 ft. take 5 (1d10) fire damage. The mane sheds bright light 20 ft.\n\n**Alpha Blaze.** Fire creatures within 30 ft. deal +1d6 fire damage on their attacks.\n\n**Pounce.** If the lion moves 20+ ft. straight and hits with a claw, target DC 14 Str or knocked prone. If prone, bonus action bite.\n\n**Actions**\n\n**Multiattack.** Bite + two Claws.\n**Bite.** +7 to hit. *Hit:* 11 (2d6 + 4) piercing + 5 (1d10) fire.\n**Claw.** +7 to hit. *Hit:* 9 (2d4 + 4) slashing.\n**Ignition Roar (Recharge 5-6).** 30 ft. cone, DC 14 Dex, 28 (8d6) fire, half on save. Flammable objects in the area ignite.\n\n**Lore:** The Cindermane Lion is not a predator — it is a force of nature, a wildfire in the shape of a beast.', art: 'dark fantasy oil painting of a massive lion with a mane of living flames roaring in a burning landscape, dramatic lighting, no text' },
  { title: 'The Pale Scholar', summary: 'CR 8 aberration that feeds on knowledge. Each hit drains a proficiency or spell slot. Immune to psychic.', tags: ['aberration', 'knowledge', 'drain', 'boss'], description: '**The Pale Scholar**\n*Medium Aberration, Neutral Evil*\n\n**AC** 15 **HP** 130 (20d8 + 40) **Speed** 30 ft., fly 30 ft. (hover)\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 10 (+0) | 16 (+3) | 14 (+2) | 22 (+6) | 18 (+4) | 16 (+3) |\n\n**Damage Immunities** psychic\n**Challenge** 8 (3,900 XP)\n\n**Knowledge Drain.** On a hit with its Mind Touch, the target loses one of the following (Pale Scholar\'s choice): proficiency in a skill or tool, one spell slot (lowest level), or one language. Lost abilities return after a long rest.\n\n**Psychic Shield.** The Pale Scholar has advantage on saves against spells cast by creatures it has drained.\n\n**Actions**\n\n**Multiattack.** Two Mind Touch attacks.\n**Mind Touch.** +6 to hit, reach 5 ft. *Hit:* 14 (4d6) psychic + Knowledge Drain.\n**Thought Lance.** Ranged, 60 ft., DC 16 Int save, 22 (4d10) psychic, half on save. On failure, the target can\'t cast spells of 3rd level or higher until end of its next turn.\n**Rewrite (Recharge 6).** One creature within 30 ft., DC 16 Wis save, or the Pale Scholar implants a false memory. The target believes one fact to be different (e.g., an ally is an enemy) for 1 minute.\n\n**Lore:** It was once a librarian in a planar archive. It read something it shouldn\'t have — and what it read, read it back.', art: 'dark fantasy oil painting of a pale floating humanoid figure with empty eyes absorbing glowing text from books, dramatic lighting, no text' },
  { title: 'The Dredge Wurm', summary: 'CR 6 monstrosity that burrows through stone. Erupts from beneath, swallows, and tunnels away with its prey.', tags: ['monstrosity', 'burrowing', 'wurm', 'ambush'], description: '**The Dredge Wurm**\n*Huge Monstrosity, Unaligned*\n\n**AC** 15 (natural armor) **HP** 115 (10d12 + 50) **Speed** 30 ft., burrow 40 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 20 (+5) | 8 (-1) | 20 (+5) | 1 (-5) | 8 (-1) | 4 (-3) |\n\n**Challenge** 6 (2,300 XP)\n\n**Tremorsense** 60 ft.\n\n**Eruption.** When the Wurm surfaces from underground, each creature within 10 ft. must DC 15 Dex save or take 14 (4d6) bludgeoning and be knocked prone.\n\n**Actions**\n\n**Bite.** +8 to hit, reach 10 ft. *Hit:* 22 (3d10 + 5) piercing. Medium or smaller: DC 15 Str or swallowed (blinded, restrained, 10 (3d6) acid start of turn, AC 15, 20 HP from inside).\n**Burrow Retreat.** The Wurm burrows underground, taking any swallowed creature with it. While underground, it can\'t be targeted by attacks or spells unless the attacker has tremorsense.\n\n**Tactical Notes:** The Wurm is a hit-and-run predator. It erupts, bites, and burrows away. The party must find ways to prevent it from retreating underground.', art: 'dark fantasy oil painting of a massive wurm erupting from stone ground beneath terrified adventurers, dramatic lighting, no text' },
  { title: 'The Velvet Court Assassin', summary: 'CR 5 fey rogue. Invisible when motionless. Poisons don\'t kill — they make the target fall in love with the assassin.', tags: ['fey', 'assassin', 'charm', 'poison'], description: '**The Velvet Court Assassin**\n*Medium Fey, Chaotic Neutral*\n\n**AC** 16 (glamoured leather) **HP** 78 (12d8 + 24) **Speed** 40 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 10 (+0) | 20 (+5) | 14 (+2) | 14 (+2) | 14 (+2) | 18 (+4) |\n\n**Challenge** 5 (1,800 XP)\n\n**Still Invisibility.** While motionless, the assassin is invisible.\n\n**Sneak Attack (3d6).** Once per turn, extra damage when attacking with advantage or when ally is within 5 ft.\n\n**Actions**\n\n**Multiattack.** Two Silken Blade attacks.\n**Silken Blade.** +8 to hit. *Hit:* 8 (1d6 + 5) piercing + Love Venom.\n**Love Venom.** DC 14 Wis save or charmed by the assassin for 1 hour. The charmed target considers the assassin their closest ally. While charmed, the target won\'t attack the assassin and will defend them. Repeat save at end of each turn, or when the target takes damage.\n**Vanishing Curtsy.** Bonus action, become invisible until end of next turn or until attacking.\n\n**Lore:** The Velvet Court doesn\'t kill its enemies. It makes them love their killers, then sends them home.', art: 'dark fantasy oil painting of an elegant fey assassin in velvet clothing with a blade dripping charm-poison, dramatic lighting, no text' },
  { title: 'Stone Mother', summary: 'CR 7 earth elemental matriarch. Creates difficult terrain, spawns rock walls, and petrifies with her gaze.', tags: ['elemental', 'earth', 'boss', 'petrify'], description: '**Stone Mother**\n*Huge Elemental, Neutral*\n\n**AC** 18 (natural armor) **HP** 138 (12d12 + 60) **Speed** 25 ft., burrow 25 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 22 (+6) | 6 (-2) | 20 (+5) | 8 (-1) | 16 (+3) | 10 (+0) |\n\n**Damage Immunities** poison\n**Damage Resistances** nonmagical bludgeoning, piercing, slashing\n**Challenge** 7 (2,900 XP)\n\n**Earth Shaper.** As a bonus action, create a 5-ft-high, 10-ft-long stone wall within 30 ft. (AC 15, 30 HP). Max 3 walls.\n\n**Actions**\n\n**Multiattack.** Two Slam attacks.\n**Slam.** +9 to hit, reach 10 ft. *Hit:* 19 (3d8 + 6) bludgeoning.\n**Petrifying Gaze.** One creature within 30 ft. must DC 15 Con save. Fail by 5+: petrified. Fail: restrained (repeating save each turn; second failure = petrified). Success: immune for 24 hours.\n**Quake (Recharge 5-6).** Each creature within 20 ft. touching the ground: DC 15 Dex save, 28 (8d6) bludgeoning + prone, half and not prone on save.\n\n**Lore:** The Stone Mother has guarded this valley since before humans named it. She is the cliff face, the canyon walls, the boulder field. She does not hate trespassers — she simply does not notice them until they dig.', art: 'dark fantasy oil painting of a massive female earth elemental rising from canyon walls with a petrifying gaze, dramatic lighting, no text' },
  { title: 'The Patchwork Knight', summary: 'CR 4 undead warrior assembled from parts of different soldiers. Each body part has a different fighting style.', tags: ['undead', 'warrior', 'patchwork', 'flesh'], description: '**The Patchwork Knight**\n*Medium Undead, Neutral Evil*\n\n**AC** 16 (mismatched plate) **HP** 85 (10d8 + 40) **Speed** 30 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 18 (+4) | 14 (+2) | 18 (+4) | 6 (-2) | 10 (+0) | 6 (-2) |\n\n**Challenge** 4 (1,100 XP)\n\n**Patchwork Body.** The Knight\'s body parts each fight differently. Roll 1d4 at the start of each turn:\n1. **Duelist\'s Arm:** +2 to hit, attacks deal +1d6.\n2. **Shield Arm:** +2 AC until end of turn.\n3. **Berserker Legs:** Speed 45 ft., advantage on first attack.\n4. **Archer\'s Eye:** Can make a ranged attack (60 ft., +6 to hit, 1d8+4).\n\n**Undead Fortitude.** DC 5 + damage Con save to stay at 1 HP (non-radiant only).\n\n**Actions**\n\n**Multiattack.** Two weapon attacks.\n**Longsword.** +7 to hit. *Hit:* 8 (1d8 + 4) slashing.\n**Shield Bash.** +7 to hit. *Hit:* 6 (1d4 + 4) bludgeoning, DC 14 Str or prone.\n\n**Lore:** Assembled by a necromancer from the bodies of four legendary warriors, the Knight fights with echoes of four different fighting styles, switching unpredictably.', art: 'dark fantasy oil painting of an undead knight assembled from different warriors body parts in mismatched armor, dramatic lighting, no text' },
  { title: 'The Dream Eater', summary: 'CR 8 aberration. Attacks sleeping creatures. In combat, can force targets to sleep then feed on their dreams.', tags: ['aberration', 'dream', 'sleep', 'psychic'], description: '**The Dream Eater**\n*Medium Aberration, Neutral Evil*\n\n**AC** 14 **HP** 120 (16d8 + 48) **Speed** 30 ft., fly 40 ft. (hover)\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 10 (+0) | 18 (+4) | 16 (+3) | 18 (+4) | 16 (+3) | 14 (+2) |\n\n**Damage Immunities** psychic\n**Challenge** 8 (3,900 XP)\n\n**Dream Feeder.** When a creature within 5 ft. is unconscious (sleeping or at 0 HP), the Dream Eater can feed as a bonus action, dealing 14 (4d6) psychic damage (no save) and healing itself for the same amount.\n\n**Actions**\n\n**Multiattack.** Two Nightmare Touch attacks.\n**Nightmare Touch.** +7 to hit, reach 5 ft. *Hit:* 11 (2d6 + 4) psychic.\n**Dream Pull (Recharge 5-6).** One creature within 30 ft., DC 16 Wis save or fall asleep for 1 minute. The creature can repeat the save when it takes damage. Elves and creatures immune to sleep are immune.\n**Nightmare Aura (1/day).** 30 ft. radius, 1 minute. Each creature that starts its turn in the aura: DC 16 Wis save or be frightened. Frightened creatures have disadvantage on the save against Dream Pull.\n\n**Lore:** It drifts between the waking world and the Plane of Dreams, feeding on the nightmares it creates. It prefers creative minds — the dreams are richer.', art: 'dark fantasy oil painting of a spectral floating creature with tendrils feeding on glowing dream wisps from a sleeping figure, dramatic lighting, no text' },
  { title: 'The Rust Tyrant', summary: 'CR 9 construct overlord. Corrodes metal weapons and armor on touch. Commands an army of Rust Drones.', tags: ['construct', 'rust', 'boss', 'corrosion'], description: '**The Rust Tyrant**\n*Large Construct, Lawful Evil*\n\n**AC** 17 (oxidized plate) **HP** 152 (16d10 + 64) **Speed** 30 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 20 (+5) | 8 (-1) | 18 (+4) | 14 (+2) | 12 (+1) | 16 (+3) |\n\n**Damage Immunities** poison, psychic\n**Challenge** 9 (5,000 XP)\n\n**Corroding Touch.** When a creature hits the Tyrant with a metal weapon, the weapon takes a permanent -1 to damage (destroyed at -5). Nonmagical metal armor touching the Tyrant gets -1 AC (destroyed at base AC -5).\n\n**Rust Commander.** Up to 4 Rust Drones (CR 1, AC 13, HP 22, corroding bite) obey its commands within 120 ft.\n\n**Actions**\n\n**Multiattack.** Two Corroding Slam attacks.\n**Corroding Slam.** +9 to hit, reach 10 ft. *Hit:* 16 (2d10 + 5) bludgeoning. Metal armor takes -1 AC.\n**Oxidation Wave (Recharge 5-6).** 30 ft. cone. Each creature: DC 16 Con save, all nonmagical metal items on the creature corrode (weapons -2, armor -2). Half effect on save.\n\n**Legendary Actions (2/round)**\n**Drone Command.** One Rust Drone takes an action.\n**Corrosion Aura (Costs 2).** Until start of its next turn, nonmagical metal within 10 ft. rusts on contact.\n\n**Tactical Notes:** The Rust Tyrant punishes metal-dependent parties. Spellcasters and monks have the advantage. If the party relies on swords and plate, this fight becomes a resource war.', art: 'dark fantasy oil painting of a massive corroded iron construct surrounded by rust drones, dramatic industrial lighting, no text' },
  { title: 'The Storm Hag', summary: 'CR 6 hag that controls weather. Her lair action changes the weather each round. Bargains are worse than combat.', tags: ['hag', 'weather', 'fey', 'boss'], description: '**The Storm Hag**\n*Medium Fey, Chaotic Evil*\n\n**AC** 15 (natural armor) **HP** 97 (13d8 + 39) **Speed** 30 ft., fly 50 ft.\n\n| STR | DEX | CON | INT | WIS | CHA |\n|-----|-----|-----|-----|-----|-----|\n| 14 (+2) | 16 (+3) | 16 (+3) | 16 (+3) | 18 (+4) | 16 (+3) |\n\n**Challenge** 6 (2,300 XP)\n\n**Innate Spellcasting (Cha).** At will: Gust of Wind, Fog Cloud. 1/day each: Call Lightning, Control Water, Sleet Storm.\n\n**Weather Shift (Lair Action, Initiative 20).** Roll 1d4:\n1. **Downpour:** Area is heavily obscured, ranged attacks have disadvantage.\n2. **Gale:** Each creature must DC 14 Str or be pushed 15 ft.\n3. **Lightning Strike:** One random creature, DC 15 Dex, 22 (4d10) lightning.\n4. **Hail:** All creatures take 7 (2d6) cold damage (no save).\n\n**Actions**\n\n**Claws.** +6 to hit. *Hit:* 10 (2d6 + 3) slashing + 7 (2d6) lightning.\n**Bargain.** The Storm Hag offers to end the fight if the party accepts a deal. Her deals are always technically fair and always catastrophically bad.\n\n**Lore:** She lives in the eye of a storm that follows her everywhere. The storm is her home, her weapon, and her beloved pet.', art: 'dark fantasy oil painting of a cackling hag floating in the center of a massive thunderstorm with lightning, dramatic lighting, no text' },
];

MONSTERS.forEach(m => {
  ITEMS.push({
    kind: 'monster',
    title: m.title,
    summary: m.summary,
    description: m.description,
    tags: m.tags,
    art_prompt: m.art,
    price_cents: 0,
    edition: '5e-2024',
    origin: 'original',
    license: 'cc-by-4.0',
  });
});

// ---- 15 Races/Subclasses ----
const RACES = [
  { title: 'Ashborn — Playable Race', summary: 'Humanoids born from volcanic eruptions. Fire resistance, ash cloud ability, and darkvision. Balanced for 5e 2024.', kind: 'other', tags: ['race', 'fire', 'volcanic', 'playable'], description: '**Ashborn**\n*"Born where the mountain breathes."*\n\nAshborn emerge from volcanic eruptions, their bodies marked with veins of cooling lava and skin the color of pumice. They are not elementals — they are as mortal as any human — but the fire that birthed them never fully leaves.\n\n**Creature Type:** Humanoid\n**Size:** Medium\n**Speed:** 30 ft.\n\n**Traits:**\n\n**Fire Resistance.** You have resistance to fire damage.\n\n**Ember Blood.** When you take fire damage, you can use your reaction to gain temporary hit points equal to your proficiency bonus. You can use this a number of times equal to your proficiency bonus, regaining all uses on a long rest.\n\n**Ash Cloud (1/long rest).** As an action, you exhale a cloud of volcanic ash in a 15-foot cone. Each creature must make a Constitution saving throw (DC = 8 + Con mod + proficiency) or be blinded until the end of your next turn.\n\n**Darkvision.** 60 feet.\n\n**Volcanic Lore.** You have proficiency in Survival.\n\n**Languages:** Common + one of your choice.\n\n*Ashborn communities form around active volcanoes, building homes from obsidian and basalt. They consider eruptions sacred — a sibling being born.*', art: 'dark fantasy oil painting portrait of a humanoid with volcanic skin and veins of cooling lava, dramatic lighting, no text' },
  { title: 'Deepshade Elf — Playable Race', summary: 'Elves from the Shadowfell. Stealth abilities, shadow step teleportation, and cold resistance. Balanced for 5e 2024.', kind: 'other', tags: ['race', 'elf', 'shadow', 'playable'], description: '**Deepshade Elf**\n*"Where light ends, we begin."*\n\nDeepshade Elves are elves who have lived in the Shadowfell for so many generations that the plane has become part of them. Their skin is ash-grey, their hair white or black, and their eyes are solid dark — no iris, no white.\n\n**Creature Type:** Humanoid\n**Size:** Medium\n**Speed:** 30 ft.\n\n**Traits:**\n\n**Darkvision.** 120 feet. You can see in magical darkness out to 30 feet.\n\n**Shadow Resistance.** You have resistance to cold damage.\n\n**Shadow Step (proficiency bonus/long rest).** As a bonus action, teleport up to 30 feet to an unoccupied space you can see that is in dim light or darkness.\n\n**Fey Ancestry.** Advantage on saves against being charmed, and magic can\'t put you to sleep.\n\n**Umbral Stealth.** You have proficiency in Stealth. When you are in dim light or darkness, you can take the Hide action as a bonus action.\n\n**Languages:** Common, Elvish.\n\n*The Shadowfell did not corrupt them. It adopted them.*', art: 'dark fantasy oil painting portrait of an elf with ash-grey skin and solid dark eyes emerging from shadows, dramatic lighting, no text' },
  { title: 'The Ironclad — Fighter Subclass', summary: 'A Fighter subclass focused on damage absorption and retribution. Take hits for allies, then unleash stored damage.', kind: 'other', tags: ['subclass', 'fighter', 'tank', 'defense'], description: '**The Ironclad — Fighter Subclass**\n*"I am the wall."*\n\n**Level 3: Absorbing Stance**\nAs a bonus action, enter Absorbing Stance (lasts 1 minute, concentration). While in this stance:\n- When an ally within 5 feet takes damage, you can use your reaction to take the damage instead.\n- Damage you absorb this way is stored (max = your Fighter level × 3).\n\n**Level 3: Retribution Strike**\nWhen you hit with a melee weapon attack, you can release stored damage. Add all stored damage to the attack\'s damage roll (the stored amount resets to 0). You can use this once per Absorbing Stance.\n\n**Level 7: Iron Skin**\nWhile in Absorbing Stance, you have resistance to bludgeoning, piercing, and slashing damage from nonmagical attacks.\n\n**Level 10: Unbreakable**\nWhen you are reduced to 0 hit points while in Absorbing Stance, you can use your reaction to drop to 1 HP instead. You can use this once per long rest.\n\n**Level 15: Fortress**\nThe range of Absorbing Stance increases to 10 feet. You can absorb damage for up to 2 allies per round.\n\n**Level 18: Living Bulwark**\nWhile in Absorbing Stance, you are immune to being frightened, stunned, or knocked prone. Your Retribution Strike deals double the stored damage.', art: 'dark fantasy oil painting of a heavily armored warrior standing protectively in front of allies, absorbing magical attacks, dramatic lighting, no text' },
  { title: 'Stonekin — Playable Race', summary: 'Rock-skinned humanoids with natural armor, tremorsense, and the ability to merge with stone briefly.', kind: 'other', tags: ['race', 'earth', 'stone', 'playable'], description: '**Stonekin**\n*"The mountain remembers."*\n\nStonekin are humanoids whose ancestors made pacts with earth elementals. Their skin is rough stone — granite, marble, or sandstone depending on their lineage — and they are denser than they appear.\n\n**Creature Type:** Humanoid\n**Size:** Medium\n**Speed:** 25 ft.\n\n**Traits:**\n\n**Natural Armor.** Your AC equals 13 + Dexterity modifier (you can still use a shield).\n\n**Tremorsense.** 10 feet (you can sense creatures touching the same ground).\n\n**Stone Merge (1/long rest).** As an action, merge with a stone surface you are touching. You are hidden, can breathe normally, and can see/hear as if you were on the surface. You can remain merged for up to 10 minutes. Emerging takes a bonus action.\n\n**Dense Build.** You have advantage on saving throws against being pushed or knocked prone.\n\n**Powerful Build.** You count as one size larger for carrying capacity.\n\n**Languages:** Common, Terran.\n\n*A Stonekin\'s lineage shows in their stone. Granite Stonekin are warriors. Marble are scholars. Sandstone are travelers.*', art: 'dark fantasy oil painting portrait of a humanoid with granite skin and glowing crystal veins, dramatic lighting, no text' },
  { title: 'The Grave Warden — Cleric Subclass', summary: 'A Cleric subclass that controls undead and uses necrotic energy for healing. Walks the line between life and death.', kind: 'other', tags: ['subclass', 'cleric', 'undead', 'necromancy'], description: '**The Grave Warden — Cleric Subclass**\n*"Death is not the enemy. Disorder is."*\n\n**Domain Spells:**\n1st: False Life, Inflict Wounds\n3rd: Gentle Repose, Ray of Enfeeblement\n5th: Animate Dead, Speak with Dead\n7th: Death Ward, Blight\n9th: Antilife Shell, Raise Dead\n\n**Level 1: Deathsight**\nYou can see the exact HP of any undead creature. You have advantage on checks to identify undead and their weaknesses.\n\n**Level 1: Necrotic Conversion**\nWhen you deal necrotic damage to an undead creature, you can convert half the damage dealt into healing for one creature within 30 feet.\n\n**Level 2: Channel Divinity — Command the Fallen**\nAs an action, one undead creature within 30 feet must make a Wisdom save or be charmed by you for 1 hour. While charmed, it obeys your verbal commands.\n\n**Level 6: Grave\'s Embrace**\nYou have resistance to necrotic damage. When you are reduced to 0 HP, you can use your reaction to remain at 1 HP (1/long rest).\n\n**Level 8: Potent Spellcasting**\nAdd your Wisdom modifier to cantrip damage.\n\n**Level 17: Lord of the Grave**\nUndead you create or charm have advantage on attack rolls and saving throws while within 30 feet of you. You can maintain Channel Divinity — Command the Fallen on up to 3 undead simultaneously.', art: 'dark fantasy oil painting of a cleric in dark robes commanding undead while channeling both holy and necrotic energy, dramatic lighting, no text' },
  { title: 'Tideborn — Playable Race', summary: 'Amphibious humanoids from deep ocean trenches. Swim speed, pressure resistance, and bioluminescent communication.', kind: 'other', tags: ['race', 'aquatic', 'ocean', 'playable'], description: '**Tideborn**\n*"The deep speaks to those who listen."*\n\nTideborn are humanoids adapted to the crushing depths of ocean trenches. Their skin ranges from deep blue to pearlescent white, with bioluminescent patterns that shift with emotion.\n\n**Creature Type:** Humanoid\n**Size:** Medium\n**Speed:** 30 ft., swim 40 ft.\n\n**Traits:**\n\n**Amphibious.** You can breathe air and water.\n\n**Pressure Adapted.** You take no damage from extreme water pressure. You have resistance to cold damage.\n\n**Bioluminescence.** You can shed bright light in a 10-foot radius and dim light for another 10 feet (toggle as bonus action). You can communicate silently with other Tideborn within 60 feet using light patterns.\n\n**Depth Charge (proficiency bonus/long rest).** As an action, release a pulse of pressurized water. Each creature within 10 feet must make a DC (8 + Con + proficiency) Constitution save or take 1d8 thunder damage and be pushed 10 feet.\n\n**Darkvision.** 60 feet.\n\n**Languages:** Common, Aquan.', art: 'dark fantasy oil painting portrait of an amphibious humanoid with bioluminescent patterns on deep blue skin, dramatic underwater lighting, no text' },
  { title: 'The Pact of Embers — Warlock Subclass', summary: 'A Warlock patron themed around dying stars and cosmic fire. Radiant/fire dual damage, stellar abilities.', kind: 'other', tags: ['subclass', 'warlock', 'fire', 'cosmic'], description: '**The Pact of Embers — Warlock Subclass**\n*"My patron is a dying star. Its last wish is destruction."*\n\n**Expanded Spell List:**\n1st: Burning Hands, Faerie Fire\n2nd: Flaming Sphere, Scorching Ray\n3rd: Fireball, Daylight\n4th: Wall of Fire, Sickening Radiance\n5th: Flame Strike, Dawn\n\n**Level 1: Ember Sight**\nYou can see normally in magical and nonmagical darkness to 120 feet. Fire and radiant sources appear to you as their true intensity, regardless of distance.\n\n**Level 1: Stellar Flare**\nWhen you deal fire damage with a spell, you can choose to deal half the damage as radiant instead. This bypasses fire resistance (but not immunity).\n\n**Level 6: Corona Shield**\nWhen you take damage from a creature within 10 feet, you can use your reaction to deal 2d8 fire + radiant damage to the attacker. You can use this a number of times equal to your Charisma modifier (min 1) per long rest.\n\n**Level 10: Supernova Heart**\nYou have resistance to fire and radiant damage. When you are reduced to 0 HP, you explode in a 20-foot radius — each creature makes a DC (spell save) Dex save, taking 4d10 fire + 4d10 radiant on failure, half on success. This can happen once per long rest.\n\n**Level 14: Dying Light**\nAs an action (1/long rest), channel your patron\'s final moments. For 1 minute: your spells deal max fire damage (no rolling), you shed bright light in 60 feet, and you are immune to fire damage. When the minute ends, you gain 3 levels of exhaustion.', art: 'dark fantasy oil painting of a warlock channeling cosmic fire from a dying star with radiant flames, dramatic cinematic lighting, no text' },
  { title: 'Wraithling — Playable Race', summary: 'Part-shadow humanoids born during eclipses. Can become incorporeal briefly, resistant to necrotic, darkvision 120 ft.', kind: 'other', tags: ['race', 'shadow', 'incorporeal', 'playable'], description: '**Wraithling**\n*"Born between light and dark."*\n\nWraithlings are humanoids born during total eclipses. Their bodies are partially translucent, their shadows move independently, and they can briefly become incorporeal.\n\n**Creature Type:** Humanoid\n**Size:** Medium\n**Speed:** 30 ft.\n\n**Traits:**\n\n**Darkvision.** 120 feet.\n\n**Necrotic Resistance.** You have resistance to necrotic damage.\n\n**Phase Shift (proficiency bonus/long rest).** As a bonus action, become incorporeal until the end of your next turn. While incorporeal, you can move through creatures and objects as difficult terrain. If you end your turn inside an object, you take 1d10 force damage and are shunted out.\n\n**Shadow Sight.** You can see through magical darkness within your darkvision range.\n\n**Unnatural Presence.** Animals are uneasy around you. You have disadvantage on Animal Handling checks but advantage on Intimidation checks.\n\n**Languages:** Common + one of your choice.\n\n*Wraithlings are not undead. They are not cursed. They are simply... between. Some cultures worship them. Others exile them. Most fear them.*', art: 'dark fantasy oil painting portrait of a translucent humanoid with an independent shadow and partially incorporeal body, dramatic lighting, no text' },
  { title: 'The Bladedancer — Rogue Subclass', summary: 'A Rogue subclass using dual wielding and dance-like combat. Bonus AC from movement, flourish attacks.', kind: 'other', tags: ['subclass', 'rogue', 'melee', 'dance'], description: '**The Bladedancer — Rogue Subclass**\n*"Every step is a feint. Every feint is a strike."*\n\n**Level 3: Dancing Steel**\nWhen you take the Attack action with a light melee weapon, you can make one additional attack with a different light melee weapon as part of the same action (no bonus action needed). You can apply Sneak Attack to either attack.\n\n**Level 3: Combat Flourish**\nIf you move at least 15 feet in a straight line before attacking, you gain +1 AC until the start of your next turn (stacks up to +3 from multiple lines of movement).\n\n**Level 9: Blade Waltz**\nYou can move through hostile creatures\' spaces without it being difficult terrain. Opportunity attacks against you have disadvantage.\n\n**Level 13: Riposte Dance**\nWhen a creature misses you with a melee attack, you can use your reaction to make one weapon attack against them. If this attack hits, it deals Sneak Attack damage (even if you\'ve already applied it this turn).\n\n**Level 17: Final Curtain**\nOnce per long rest, as an action, make a melee weapon attack against each creature within 5 feet (up to 6 targets). Each attack can apply half your Sneak Attack dice.', art: 'dark fantasy oil painting of a rogue performing an acrobatic dual-blade combat dance, dramatic cinematic lighting, no text' },
  { title: 'Thornblood — Playable Race', summary: 'Plant-humanoid hybrids. Regeneration in sunlight, thorn armor reaction, and poison resistance.', kind: 'other', tags: ['race', 'plant', 'nature', 'playable'], description: '**Thornblood**\n*"We are the forest\'s answer."*\n\nThornbloods are humanoids infused with plant matter — their hair is leafy vines, their skin has a green-brown bark texture, and sharp thorns grow from their forearms and shoulders.\n\n**Creature Type:** Humanoid (Plant)\n**Size:** Medium\n**Speed:** 30 ft.\n\n**Traits:**\n\n**Photosynthetic Recovery.** While in direct sunlight, you regain 1 HP at the start of each of your turns if you have at least 1 HP.\n\n**Thorn Armor.** When a creature hits you with a melee attack from within 5 feet, they take 1d4 piercing damage (increases to 2d4 at level 11).\n\n**Poison Resistance.** You have resistance to poison damage and advantage on saves against the poisoned condition.\n\n**Rooted Rest.** During a long rest, you can root yourself in soil. If you do, the rest takes 4 hours instead of 8, and you have advantage on the first attack roll or ability check you make after waking.\n\n**Natural Camouflage.** You have advantage on Stealth checks in natural terrain with vegetation.\n\n**Languages:** Common, Sylvan.', art: 'dark fantasy oil painting portrait of a humanoid with bark-like skin thorns on shoulders and leafy vine hair, dramatic forest lighting, no text' },
  { title: 'The Siege Master — Artificer Subclass', summary: 'An Artificer subclass that builds deployable turrets, barriers, and siege weapons from scrap materials.', kind: 'other', tags: ['subclass', 'artificer', 'siege', 'constructs'], description: '**The Siege Master — Artificer Subclass**\n*"Give me ten minutes and some scrap. I\'ll give you a fortress."*\n\n**Level 3: Deployable Turret**\nAs an action, deploy a Small turret in an unoccupied space within 5 feet. The turret has AC 15, HP = 5 × your Artificer level, and makes a ranged attack each turn (+your spell attack, 1d8+Int force, 60 ft.). You can have 1 turret active (2 at level 9). Deploying costs 25 gp in materials.\n\n**Level 3: Field Barrier**\nAs an action, create a 10-ft-wide, 5-ft-tall barrier in an unoccupied space within 10 feet. AC 15, HP = 3 × Artificer level. Provides half cover. Max 2 barriers. Costs 10 gp in materials.\n\n**Level 5: Turret Upgrade**\nChoose one upgrade per turret: Flame (15 ft. cone, 2d6 fire), Shock (single target, 2d10 lightning, stun DC 14 on crit), or Heal (1d8+Int to one ally within 30 ft.).\n\n**Level 9: Siege Engine**\nOnce per long rest, spend 1 minute and 100 gp to build a Medium siege weapon (ballista or catapult). Range 120/480 ft., 3d10 bludgeoning. Requires an action to fire.\n\n**Level 15: Fortress Protocol**\nAll your turrets and barriers within 30 feet gain +2 AC and resistance to all damage. You can command all turrets to fire simultaneously as a single action.', art: 'dark fantasy oil painting of a gnome artificer surrounded by deployed turrets and mechanical barriers on a battlefield, dramatic lighting, no text' },
  { title: 'Crystalvein Dwarf — Playable Race', summary: 'Dwarves whose bodies contain living crystal growths. Can create light, resist psychic damage, and sense magic.', kind: 'other', tags: ['race', 'dwarf', 'crystal', 'playable'], description: '**Crystalvein Dwarf**\n*"The stone sings through us."*\n\nCrystalvein Dwarves are a rare dwarven lineage whose bodies contain veins of living crystal. The crystals grow slowly over their lifetime, and the oldest Crystalveins are as much gem as flesh.\n\n**Creature Type:** Humanoid\n**Size:** Medium\n**Speed:** 25 ft.\n\n**Traits:**\n\n**Darkvision.** 60 feet.\n\n**Crystal Resonance.** You have resistance to psychic damage. The crystals in your body vibrate in the presence of magic — you can sense magic within 10 feet without using a spell.\n\n**Prism Light.** As a bonus action, your crystals emit bright light in a 20-foot radius and dim light for another 20 feet. You can change the light\'s color. Toggle off as a bonus action.\n\n**Crystal Shard (proficiency bonus/long rest).** As a bonus action, grow and launch a crystal shard. Ranged weapon attack, 30 ft., 1d6 + Con modifier piercing damage.\n\n**Dwarven Resilience.** Advantage on saves against poison, resistance to poison damage.\n\n**Languages:** Common, Dwarvish.', art: 'dark fantasy oil painting portrait of a dwarf with crystal growths emerging from their skin emitting colorful light, dramatic lighting, no text' },
  { title: 'The Herald — Bard Subclass', summary: 'A Bard subclass that uses proclamations and decrees as battle commands. Grants ally bonuses based on declared strategies.', kind: 'other', tags: ['subclass', 'bard', 'commander', 'support'], description: '**The Herald — Bard Subclass**\n*"Hear me and be emboldened!"*\n\n**Level 3: Battle Proclamation**\nAs a bonus action, declare one of the following strategies (lasts 1 minute, concentration):\n\n- **Advance!** Allies within 30 feet gain +10 ft. movement speed.\n- **Hold the Line!** Allies within 30 feet gain +1 AC.\n- **Strike True!** Allies within 30 feet gain +1 to attack rolls.\n\nYou can change your proclamation as a bonus action.\n\n**Level 3: Herald\'s Voice**\nYour Bardic Inspiration die increases range to 60 feet. When an ally uses your Bardic Inspiration, they also gain temporary HP equal to the roll.\n\n**Level 6: Decree of Valor**\nWhen an ally within 30 feet hits with an attack during your proclamation, they deal extra damage equal to your Charisma modifier.\n\n**Level 14: Grand Proclamation**\nOnce per long rest, make a Grand Proclamation: all three base proclamations apply simultaneously for 1 minute (no concentration). Additionally, allies within 30 feet have advantage on saving throws against being frightened.', art: 'dark fantasy oil painting of a bard in armor on a battlefield raising a banner and shouting commands to rallying soldiers, dramatic lighting, no text' },
  { title: 'Veilwalker — Playable Race', summary: 'Humanoids who exist partially in the Ethereal Plane. Can see ethereal creatures, phase through objects, resist force damage.', kind: 'other', tags: ['race', 'ethereal', 'phase', 'playable'], description: '**Veilwalker**\n*"Two worlds, one step."*\n\nVeilwalkers exist simultaneously in the Material and Ethereal Planes. They appear slightly translucent, and their movements sometimes lag behind their bodies, as if two versions of them are walking a beat apart.\n\n**Creature Type:** Humanoid\n**Size:** Medium\n**Speed:** 30 ft.\n\n**Traits:**\n\n**Ethereal Sight.** You can see into the Ethereal Plane out to 30 feet.\n\n**Force Resistance.** You have resistance to force damage.\n\n**Phase Walk (proficiency bonus/long rest).** As an action, partially shift into the Ethereal Plane for 1 round. While phased, you can move through solid objects and creatures (difficult terrain). You are visible as a ghostly outline. Attacks against you have disadvantage.\n\n**Dual Presence.** You have advantage on Perception checks to detect hidden or invisible creatures.\n\n**Veil Touched.** You are resistant to effects that would banish or plane shift you unwillingly (advantage on the save).\n\n**Languages:** Common + one of your choice.\n\n*They say Veilwalkers are the children of the border between worlds. No one is sure which world they truly belong to — including the Veilwalkers themselves.*', art: 'dark fantasy oil painting portrait of a translucent humanoid existing partially in two overlapping planes of reality, dramatic lighting, no text' },
  { title: 'The Sandweaver — Monk Subclass', summary: 'A Monk subclass using desert combat arts. Sand manipulation, blinding strikes, and mirages as defensive abilities.', kind: 'other', tags: ['subclass', 'monk', 'desert', 'sand'], description: '**The Sandweaver — Monk Subclass**\n*"The desert fights with patience."*\n\n**Level 3: Sand Manipulation**\nYou can spend 1 ki point to create one of the following effects:\n\n- **Sand Veil:** You are lightly obscured until the start of your next turn (+2 AC against ranged attacks).\n- **Blinding Sand:** On a successful unarmed strike, the target must DC (Ki save) Con save or be blinded until end of their next turn.\n- **Sand Walk:** You leave no tracks and ignore difficult terrain from sand, earth, or rubble for 10 minutes.\n\n**Level 6: Mirage Step**\nWhen an attack misses you, you can spend 1 ki point as a reaction to leave an illusory duplicate in your space and move up to 15 feet without provoking opportunity attacks. The duplicate lasts until the start of your next turn (enemies must DC Ki save Int check to tell which is real).\n\n**Level 11: Desert Storm**\nAs an action, spend 3 ki points. 20-foot radius, DC Ki save Con save, 6d8 slashing (sand), half on save. Area becomes difficult terrain for 1 minute.\n\n**Level 17: Sandform**\nSpend 5 ki points. For 1 minute, your body becomes living sand: immune to bludgeoning/piercing/slashing, can move through spaces as small as 1 inch, and your unarmed strikes deal +2d6 slashing.', art: 'dark fantasy oil painting of a monk in desert garb manipulating swirling sand in combat stances, dramatic lighting, no text' },
];

RACES.forEach(r => {
  ITEMS.push({
    kind: r.kind || 'other',
    title: r.title,
    summary: r.summary,
    description: r.description,
    tags: r.tags,
    art_prompt: r.art,
    price_cents: 0,
    edition: '5e-2024',
    origin: 'original',
    license: 'cc-by-4.0',
  });
});

// ---- 15 Encounter Map & Atmosphere Packs ----
const MAPS = [
  { title: 'The Sunken Cathedral', summary: 'A partially flooded gothic cathedral with crumbling pillars, waist-deep water, and an altar that glows with trapped divine energy.', tags: ['map', 'cathedral', 'flooded', 'gothic'], description: '**The Sunken Cathedral — Encounter Map & Atmosphere Pack**\n\n**Setting:** A grand cathedral, half-submerged in murky water. The nave is waist-deep; the altar platform rises above the waterline. Stained glass windows cast colored light across the surface.\n\n**Grid:** 40×30 squares (5 ft. each)\n\n**Environmental Features:**\n- **Waist-Deep Water (blue zones):** Difficult terrain. Small creatures must swim. Stealth checks have disadvantage.\n- **Crumbling Pillars (6):** Half cover. Each has AC 15, 20 HP. Destroying one collapses 10 ft. of ceiling above it (DC 14 Dex, 2d10 bludgeoning).\n- **Glowing Altar:** Radiates dim light 20 ft. Undead within the light have disadvantage on attacks. Touching the altar heals 2d8 (once per creature).\n- **Submerged Passage:** Hidden below the water (DC 14 Perception). Leads to a sacristy with lootable relics.\n\n**Mood Cues:**\n- **Lighting:** Dim, colored by stained glass. Candles float on the water.\n- **Sound:** Dripping water, distant chanting (echoes from the stone).\n- **Music:** Low organ drone, minor key. Reverb-heavy. Occasional choir swell.\n\n**Suggested Encounters:**\n- 4 Ghouls lurking beneath the water, bursting up when PCs reach the altar\n- A Water Weird bound to the font at the entrance\n- A corrupted angel kneeling at the altar, weeping, who attacks if disturbed', art: 'dark fantasy oil painting of a flooded gothic cathedral interior with glowing altar and colored light through stained glass, dramatic lighting, no text' },
  { title: 'The Bone Bridge', summary: 'A bridge made of fused skeletal remains spanning a bottomless chasm. The bones shift and groan underfoot.', tags: ['map', 'bridge', 'undead', 'chasm'], description: '**The Bone Bridge — Encounter Map & Atmosphere Pack**\n\n**Setting:** A 60-foot bridge spanning a seemingly bottomless chasm. The bridge is made entirely of fused bones — skulls, ribcages, femurs — all interlocked like living masonry.\n\n**Grid:** 15×60 squares (5 ft. each), plus 20×20 platforms on each side\n\n**Environmental Features:**\n- **Bone Bridge:** 15 ft. wide. The bones shift — Dex (Acrobatics) DC 10 to move at full speed, or half speed safely.\n- **Grasping Hands (3 zones):** Skeletal arms reach up. DC 13 Str save at start of turn or restrained.\n- **Bone Rain:** Every 3 rounds, bones fall from the cavern ceiling. DC 12 Dex save, 2d6 bludgeoning.\n- **The Chasm:** 500+ ft. deep. Creatures that fall disappear into darkness. Feather Fall works.\n\n**Mood Cues:**\n- **Lighting:** Near-darkness. Faint green bioluminescence from deep in the chasm.\n- **Sound:** Bone creaking, distant wailing, the bridge groaning with each step.\n- **Music:** Deep bass rumble, staccato percussion like bones clicking.\n\n**Suggested Encounters:**\n- A Bone Golem that IS the bridge (the entire bridge is one creature)\n- 2 Wraiths emerging from the chasm walls\n- A rival adventuring party approaching from the other side', art: 'dark fantasy oil painting of a bridge made of interlocked bones and skulls spanning a dark chasm, dramatic lighting, no text' },
  { title: 'The Crystal Cavern', summary: 'A cavern of massive natural crystals that amplify magic. Spells gain power but become unpredictable.', tags: ['map', 'cavern', 'crystal', 'magic'], description: '**The Crystal Cavern — Encounter Map & Atmosphere Pack**\n\n**Setting:** A natural cavern filled with crystals ranging from fist-sized to 15 feet tall. The crystals hum with magical resonance.\n\n**Grid:** 50×50 squares (5 ft. each)\n\n**Environmental Features:**\n- **Crystal Formations (12):** Full cover. If hit by a spell, the crystal absorbs it and releases it in a random direction next round.\n- **Resonance Zones (4):** Spells cast in these zones are upcast by 1 level but the caster must make a DC 12 Arcana check or the spell targets are randomized.\n- **Crystal Floor:** Bright light throughout. Stealth has disadvantage. Dex save DC 12 or fall prone when running (the floor is smooth and slippery).\n- **Harmonic Chamber (center):** A 10-ft circle where all damage is doubled (for everyone).\n\n**Mood Cues:**\n- **Lighting:** Brilliant prismatic light. Almost painfully bright.\n- **Sound:** A constant harmonic hum, like a tuning fork. Louder near large crystals.\n- **Music:** Glass harmonica, shimmering pads, rising tones.\n\n**Suggested Encounters:**\n- An Arcane Eye (CR 4 construct) harvesting crystal fragments\n- A young Phase Spider using the resonance zones to teleport unpredictably\n- A trapped wizard who accidentally supercharged a spell and can\'t stop it', art: 'dark fantasy oil painting of a massive crystal cavern with glowing prismatic crystals of various sizes, dramatic lighting, no text' },
  { title: 'The Gallows Tree', summary: 'A massive dead tree at a crossroads where criminals were hanged. The nooses still hang. The dead don\'t rest easy.', tags: ['map', 'tree', 'undead', 'crossroads'], description: '**The Gallows Tree — Encounter Map & Atmosphere Pack**\n\n**Setting:** A crossroads dominated by a massive dead oak. Dozens of rope nooses hang from its branches. The ground beneath is salted and barren.\n\n**Grid:** 40×40 squares (5 ft. each)\n\n**Environmental Features:**\n- **The Gallows Tree:** Huge. Provides cover. Climbing DC 12. 15 nooses hang from branches at 10-15 ft. height.\n- **Animate Nooses (3 at a time):** As a lair action, nooses lash out. +6 to hit, reach 15 ft. Hit: grappled and lifted (escape DC 14). Lifted creatures take 1d6 bludgeoning per round.\n- **Salted Earth (20 ft. radius):** Undead that start their turn here take 1d6 radiant damage. The salt can be disrupted.\n- **Four Roads:** Each road has light fog. Creatures appearing from the fog have advantage on their first attack.\n\n**Mood Cues:**\n- **Lighting:** Perpetual dusk. The tree casts long shadows even when the sun is directly overhead.\n- **Sound:** Creaking rope, cawing crows, distant wind.\n- **Music:** Sparse folk strings, minor key. A slow dirge tempo.\n\n**Suggested Encounters:**\n- 6 Specters (the hanged criminals) manifesting at dusk\n- A Revenant hunting the judge who wrongly condemned them\n- A group of bandits using the tree\'s reputation to avoid pursuit', art: 'dark fantasy oil painting of a massive dead tree at a misty crossroads with hanging nooses and spectral figures, dramatic lighting, no text' },
  { title: 'The Forge of Sorrows', summary: 'A cursed dwarven forge where weapons weep molten tears. The heat intensifies near the central anvil.', tags: ['map', 'forge', 'dwarven', 'cursed'], description: '**The Forge of Sorrows — Encounter Map & Atmosphere Pack**\n\n**Setting:** An ancient dwarven forge, still operational. The forge fire burns with blue-white flame. Weapons on racks weep drops of molten metal.\n\n**Grid:** 35×45 squares (5 ft. each)\n\n**Environmental Features:**\n- **Central Forge:** 10 ft. radius of extreme heat. 2d6 fire damage to start of turn within 5 ft. Metal weapons within 10 ft. glow red-hot (+1d4 fire damage on hit, but if dropped, DC 12 Dex or 1d4 fire to pick up).\n- **Weapon Racks (8):** Each holds 2d4 weapons. The weapons animate if the forge is threatened (use Flying Sword stat block).\n- **Slag Channels:** 5-ft-wide channels of molten slag. 4d6 fire damage to enter. Can be crossed with a running jump (15 ft.).\n- **The Sorrowful Anvil:** Weapons forged here are +1 but cursed (the DM decides the curse). Destroying the anvil ends all curses but releases the trapped souls inside as 2d4 Shadows.\n\n**Mood Cues:**\n- **Lighting:** Blue-white from the forge, orange from the slag. Deep shadows in corners.\n- **Sound:** Rhythmic hammering (no one is at the anvil). Hissing steam. Whispered names.\n- **Music:** Industrial percussion, anvil strikes in irregular rhythm, low droning vocals.', art: 'dark fantasy oil painting of a dwarven forge with blue-white flame and weeping weapons with molten metal tears, dramatic lighting, no text' },
  { title: 'The Mirrored Ballroom', summary: 'An abandoned noble\'s ballroom where every mirror shows a different time. Reflections act independently.', tags: ['map', 'ballroom', 'mirrors', 'time'], description: '**The Mirrored Ballroom — Encounter Map & Atmosphere Pack**\n\n**Setting:** A grand ballroom with floor-to-ceiling mirrors on three walls. The mirrors show the room at different points in its history — some show it pristine and full of dancers; others show it burning.\n\n**Grid:** 40×30 squares (5 ft. each)\n\n**Environmental Features:**\n- **Mirrors (12 panels):** Each shows a different time. Reflections of PCs act independently. Breaking a mirror (AC 10, 10 HP) releases the timeframe as a hazard.\n- **Mirror Hazards (when broken):** Roll 1d4: 1) Past dancers manifest as 2 Specters; 2) Fire erupts (15 ft., 3d6 fire); 3) The room floods with water from a time when the building was submerged; 4) Silence — no sound in 20 ft. for 1 minute.\n- **Dance Floor:** Smooth marble. DC 10 Dex or fall prone when running. The floor reflects perfectly — creatures can be attacked from above and below.\n- **Chandelier:** Huge, still lit. AC 12, 15 HP. Falls in a 10 ft. radius, DC 14 Dex, 3d8 bludgeoning + 1d6 fire.\n\n**Mood Cues:**\n- **Lighting:** Brilliant chandelier. Mirrors multiply the light.\n- **Sound:** Faint waltz music, laughter, the clink of glasses (from the mirrors).\n- **Music:** Distorted waltz, like a music box winding down. Occasional time skips.', art: 'dark fantasy oil painting of a grand ballroom with floor-to-ceiling mirrors showing different time periods, dramatic chandelier lighting, no text' },
  { title: 'The Fungal Grotto', summary: 'A mushroom-filled underground grotto with spore clouds, bioluminescence, and carnivorous fungi.', tags: ['map', 'underground', 'fungus', 'nature'], description: '**The Fungal Grotto — Encounter Map & Atmosphere Pack**\n\n**Setting:** An underground grotto dominated by massive mushrooms (10-20 ft. tall). Bioluminescent fungi provide dim purple and green light. Spore clouds drift lazily.\n\n**Grid:** 45×35 squares (5 ft. each)\n\n**Environmental Features:**\n- **Giant Mushrooms (8):** Full cover. Springy — creatures pushed into them bounce 10 ft. in a random direction.\n- **Spore Clouds (3 zones):** DC 12 Con save at start of turn or one of: 1) Poisoned for 1 round; 2) Hallucinate (attack nearest creature, friend or foe); 3) Fall asleep for 1 round.\n- **Carnivorous Fungus (2):** 10 ft. radius. Creatures that end their turn within are grappled (escape DC 13) and take 1d8 acid.\n- **Luminous Path:** A trail of glowing mushrooms leads deeper. Following it safely avoids the spore clouds.\n\n**Mood Cues:**\n- **Lighting:** Dim purple-green bioluminescence. Pulsing slowly.\n- **Sound:** Soft popping (spores releasing), dripping water, the squelch of fungal growth.\n- **Music:** Ambient synth pads, low frequencies, rhythmic pulsing like a heartbeat.\n\n**Suggested Encounters:**\n- A Myconid colony that communicates through spores (not hostile — unless disturbed)\n- 2 Violet Fungi + 4 Gas Spores (look like beholders in the dim light)\n- A druid who has bonded with the grotto and considers intruders a disease', art: 'dark fantasy oil painting of an underground grotto filled with massive bioluminescent mushrooms and drifting spore clouds, dramatic lighting, no text' },
  { title: 'The Frozen Throne Room', summary: 'A palace throne room encased in magical ice. The ice preserves a court frozen mid-celebration. The cold is supernatural.', tags: ['map', 'ice', 'palace', 'frozen'], description: '**The Frozen Throne Room — Encounter Map & Atmosphere Pack**\n\n**Setting:** A grand throne room, perfectly preserved under a layer of magical ice. Courtiers are frozen mid-toast, mid-dance, mid-conversation. The king sits on his throne, frozen with a smile.\n\n**Grid:** 50×30 squares (5 ft. each)\n\n**Environmental Features:**\n- **Supernatural Cold:** All creatures take 1d4 cold damage at the start of each turn unless resistant/immune.\n- **Frozen Courtiers (20+):** Obstacles (difficult terrain). If the ice is broken, the courtier shatters. Breaking 5+ courtiers summons the Ice Crown (boss).\n- **Slick Floor:** The floor is ice. Movement over 20 ft. in a turn requires DC 12 Dex or fall prone.\n- **The Frozen King:** Touching the throne triggers the encounter. The king is not dead — he is the source of the cold.\n\n**Mood Cues:**\n- **Lighting:** Blue-white. Everything sparkles. Breath is visible.\n- **Sound:** Absolute silence, broken by the crack of ice when anyone moves.\n- **Music:** Crystalline piano, sparse and echoing. Long sustain. No warmth.\n\n**Suggested Encounters:**\n- The Frozen King awakens as an Ice Lich (CR 7)\n- 4 Frozen Courtiers animate as Ice Mephits\n- A rival party trying to steal the crown triggers the encounter for everyone', art: 'dark fantasy oil painting of a grand throne room encased in magical ice with frozen courtiers mid-celebration, dramatic blue lighting, no text' },
  { title: 'The War Trench', summary: 'A muddy battlefield trench system with barbed wire, arrow slits, and no-man\'s land between two positions.', tags: ['map', 'war', 'trench', 'battlefield'], description: '**The War Trench — Encounter Map & Atmosphere Pack**\n\n**Setting:** A network of trenches cut into muddy ground. Two fortified positions face each other across 60 ft. of open ground (no-man\'s land). The air smells of smoke and iron.\n\n**Grid:** 60×40 squares (5 ft. each)\n\n**Environmental Features:**\n- **Trenches (5 ft. deep):** Full cover from ranged attacks. Difficult terrain (mud). Connecting tunnels between positions.\n- **No-Man\'s Land:** Open ground with scattered debris (half cover). Crossing takes 2 rounds at normal speed. Any creature in the open can be targeted by both sides.\n- **Arrow Slits (4 per side):** Provide three-quarters cover. Can fire through them normally.\n- **Barbed Wire (3 zones):** DC 13 Dex or take 1d4 piercing and speed reduced to 0 until freed (DC 13 Str or Dex).\n\n**Mood Cues:**\n- **Lighting:** Overcast. Grey. Flashes of fire from the opposing line.\n- **Sound:** Distant drums, shouted commands, the thud of arrows into mud.\n- **Music:** Military percussion, low brass, tension-building ostinato.', art: 'dark fantasy oil painting of muddy war trenches on a dark battlefield with arrow slits and barbed wire, dramatic overcast lighting, no text' },
  { title: 'The Clockwork Library', summary: 'A library where the shelves rotate on mechanical tracks. The layout changes every minute, trapping readers inside.', tags: ['map', 'library', 'clockwork', 'puzzle'], description: '**The Clockwork Library — Encounter Map & Atmosphere Pack**\n\n**Setting:** A circular library with three concentric rings of bookshelves mounted on mechanical tracks. Every 6 rounds (1 minute), the rings rotate, changing paths and trapping or freeing creatures.\n\n**Grid:** 40×40 squares (5 ft. each), circular\n\n**Environmental Features:**\n- **Rotating Rings (3):** Outer ring moves clockwise, middle counter-clockwise, inner clockwise. Creatures on a ring move with it. DC 13 Dex to jump between rings during rotation.\n- **Shelving (30 ft. tall):** Climbing DC 12. Books can be thrown (improvised weapon, 1d4). Some books are trapped (1d6 fire, DC 12 Dex).\n- **Central Desk:** The control mechanism. DC 16 Arcana or Tinker\'s Tools to stop the rotation, DC 20 to reverse it.\n- **Reading Alcoves (4):** Safe zones where the shelves don\'t reach. Each contains a clue to stopping the mechanism.\n\n**Mood Cues:**\n- **Lighting:** Warm, from floating candles. The light moves with the shelves.\n- **Sound:** Grinding gears, clicking mechanisms, pages rustling.\n- **Music:** Ticking metronome layered with string quartet, shifting tempo.', art: 'dark fantasy oil painting of a circular library with rotating mechanical bookshelves on clockwork tracks, dramatic warm lighting, no text' },
  { title: 'The Petrified Battlefield', summary: 'An ancient battlefield where every combatant was turned to stone mid-fight. The statues are arranged in frozen combat.', tags: ['map', 'battlefield', 'petrified', 'statues'], description: '**The Petrified Battlefield — Encounter Map & Atmosphere Pack**\n\n**Setting:** Hundreds of stone warriors frozen in combat. Swords locked, shields raised, arrows suspended in stone. Two armies, petrified instantly by a spell that ended the war.\n\n**Grid:** 60×40 squares (5 ft. each)\n\n**Environmental Features:**\n- **Stone Warriors (50+):** Difficult terrain throughout. Provide half or three-quarters cover depending on pose. Some are balanced precariously — DC 12 Str to topple, 2d6 bludgeoning in 5 ft.\n- **The Petrification Zone (center):** A 20-ft. radius where the original spell lingers. DC 15 Con save at start of turn or begin turning to stone (restrained → petrified on next failed save).\n- **Stone Arrows:** Suspended in the air. Can be dislodged (1d6 piercing, 10 ft. area).\n- **The General\'s Statue:** At the center, a stone general holds the artifact that cast the spell. Removing it ends the petrification zone but animates 1d6 stone warriors as Animated Armor.\n\n**Mood Cues:**\n- **Lighting:** Harsh daylight. Long shadows from the statues.\n- **Sound:** Wind through stone. Creaking as old stone shifts.\n- **Music:** Silence. Then distant war drums, growing louder.', art: 'dark fantasy oil painting of an ancient battlefield with hundreds of stone warrior statues frozen mid-combat, dramatic lighting, no text' },
  { title: 'The Dreamscape Clearing', summary: 'A forest clearing that exists in the border between waking and dreaming. Reality is soft and malleable.', tags: ['map', 'dream', 'forest', 'fey'], description: '**The Dreamscape Clearing — Encounter Map & Atmosphere Pack**\n\n**Setting:** A forest clearing where the boundary between the waking world and the Plane of Dreams is paper-thin. Colors are too vivid. Gravity is optional. Time loops.\n\n**Grid:** 35×35 squares (5 ft. each)\n\n**Environmental Features:**\n- **Soft Reality (entire area):** At the start of each round, roll 1d6:\n  1) Gravity reverses for 1 round; 2) All creature positions swap randomly; 3) The terrain becomes underwater (swim speed needed); 4) Everything is in slow motion (half speed, half damage); 5) Double vision (all attacks have disadvantage); 6) Normal.\n- **Dream Trees (6):** Touch a tree as an action — DC 13 Wisdom check to reshape it into a bridge, wall, or weapon (1 round duration).\n- **Memory Pools (3):** Looking into a pool forces a DC 12 Wis save or the creature relives a memory (stunned for 1 round, but gains inspiration).\n- **The Dreamer:** At the center, a sleeping fey creature. If woken, the clearing vanishes and everyone appears in the nearest real forest.\n\n**Mood Cues:**\n- **Lighting:** Ever-shifting. Dawn, dusk, moonlight, all at once.\n- **Sound:** Whispering voices, laughter, lullabies in unknown languages.\n- **Music:** Ambient ethereal pads, reversed sounds, childlike melodies.', art: 'dark fantasy oil painting of a surreal forest clearing with impossible colors and floating elements at the border of dreams, dramatic lighting, no text' },
  { title: 'The Alchemist\'s Lab', summary: 'A multi-level alchemy laboratory with volatile chemicals, unstable experiments, and an apparatus that could explode.', tags: ['map', 'alchemy', 'lab', 'urban'], description: '**The Alchemist\'s Lab — Encounter Map & Atmosphere Pack**\n\n**Setting:** A three-story tower interior converted into an alchemy laboratory. Bubbling cauldrons, shelves of reagents, a central distillation apparatus three stories tall.\n\n**Grid:** 25×25 squares (5 ft. each), 3 levels\n\n**Environmental Features:**\n- **Volatile Chemicals (8 stations):** Each contains a random potion effect. Destroying one (AC 10, 5 HP) triggers an explosion: 10 ft. radius, 2d6 damage of a random type (fire/acid/cold/lightning/poison), DC 12 Dex half.\n- **Central Apparatus:** AC 15, 50 HP. If destroyed, the entire lab explodes: 30 ft. radius, 6d6 fire + 4d6 acid, DC 15 Dex half.\n- **Unstable Floor (Level 2):** Sections are weakened by acid. DC 13 Dex or fall through to Level 1 (1d6 falling + land in something unpleasant).\n- **Reagent Shelves:** As an action, grab a random reagent and throw it (20 ft.). Roll 1d4: 1) Acid Flask (2d6 acid); 2) Alchemist\'s Fire; 3) Smoke Bomb (heavily obscured 10 ft.); 4) Healing Draught (heals 1d8).\n\n**Mood Cues:**\n- **Lighting:** Green-tinted from bubbling liquids. Flickering.\n- **Sound:** Bubbling, hissing, glass tinkling, dripping.\n- **Music:** Percussive glass, synthesizer arpeggios, building tension.', art: 'dark fantasy oil painting of a multi-level alchemy laboratory with bubbling cauldrons and a massive distillation apparatus, dramatic green lighting, no text' },
  { title: 'The Sandstorm Ruins', summary: 'Desert ruins half-buried in sand during a magical sandstorm. Visibility is 15 feet. The storm is getting worse.', tags: ['map', 'desert', 'ruins', 'storm'], description: '**The Sandstorm Ruins — Encounter Map & Atmosphere Pack**\n\n**Setting:** Ancient stone ruins partially buried by advancing dunes, battered by a magical sandstorm that reduces visibility to 15 feet.\n\n**Grid:** 50×40 squares (5 ft. each)\n\n**Environmental Features:**\n- **Sandstorm:** Visibility 15 ft. Beyond that, heavily obscured. Ranged attacks beyond 15 ft. have disadvantage. Every 3 rounds, the storm intensifies: DC 12 Str save or be pushed 10 ft.\n- **Sand Dunes (6):** High ground (+2 to attack rolls downhill). Climbing is difficult terrain. Sand avalanche if 3+ creatures stand on one dune simultaneously (DC 13 Dex or buried — restrained, DC 13 Str to escape).\n- **Buried Columns (4):** Partial cover. Can be toppled (DC 16 Str) to create bridges or crush enemies (3d6 bludgeoning, 10 ft. line).\n- **The Oasis (center):** A 15 ft. pool of still water. The storm doesn\'t reach it. Resting here for 1 minute grants resistance to the storm effects for 10 minutes.\n\n**Mood Cues:**\n- **Lighting:** Orange-brown haze. Sun is a dim disc through the sand.\n- **Sound:** Howling wind, sand striking stone, distant thunder.\n- **Music:** Middle Eastern percussion, droning strings, wind instruments.', art: 'dark fantasy oil painting of ancient stone ruins being engulfed by a magical sandstorm in a desert, dramatic orange lighting, no text' },
  { title: 'The Shipwreck Interior', summary: 'The inside of a capsized galleon underwater. Air pockets, rising water, and something in the hold.', tags: ['map', 'shipwreck', 'underwater', 'nautical'], description: '**The Shipwreck Interior — Encounter Map & Atmosphere Pack**\n\n**Setting:** The interior of a capsized galleon resting on the sea floor. The ship is upside-down, creating air pockets in some rooms. Water is slowly filling every chamber.\n\n**Grid:** 50×15 squares (5 ft. each), 3 decks\n\n**Environmental Features:**\n- **Air Pockets (4):** Each holds about 10 minutes of air. Bubbles escape upward (downward, since the ship is flipped).\n- **Rising Water:** Every 5 rounds, the water level rises 1 foot. After 15 rounds, all chambers are flooded.\n- **Barnacle Growth:** Walls and floors are sharp. Creatures pushed into walls take 1d4 slashing.\n- **The Cargo Hold:** The deepest chamber (now the highest, since capsized). Contains the treasure and whatever is guarding it. Accessible through a hatch that is currently submerged.\n- **Structural Weakness (3 bulkheads):** AC 12, 20 HP. Breaking one floods the adjacent chamber instantly but may create an escape route.\n\n**Mood Cues:**\n- **Lighting:** Murky blue-green from light filtering through the hull. Bioluminescent fish.\n- **Sound:** Creaking timber, bubbling air, the groan of pressure on the hull.\n- **Music:** Muffled bass, slow tempo, whale-song ambience.\n\n**Suggested Encounters:**\n- A Giant Octopus in the cargo hold, guarding eggs\n- 4 Drowned Dead (re-skinned zombies) — the original crew\n- A trapped water genasi merchant who survived by creating air pockets', art: 'dark fantasy oil painting of the interior of a capsized underwater shipwreck with air pockets and murky light, dramatic lighting, no text' },
];

MAPS.forEach(m => {
  ITEMS.push({
    kind: 'map',
    title: m.title,
    summary: m.summary,
    description: m.description,
    tags: m.tags,
    art_prompt: m.art,
    price_cents: 0,
    edition: '5e-2024',
    origin: 'original',
    license: 'cc-by-4.0',
  });
});

// ---- Apply pricing: 65 free, 35 paid ----
// Adventures (25): first 15 free, 10 paid ($2.99-$4.99)
// Magic Items (25): all free
// Monsters (20): first 15 free, 5 paid ($1.99)
// Races/Subclasses (15): first 5 free, 10 paid ($2.99-$3.99)
// Maps (15): first 5 free, 10 paid ($1.99-$2.99)
const PAID_PRICES = [199, 299, 399, 499];
let freeCount = 0, paidCount = 0;
ITEMS.forEach((item, i) => {
  if (i >= 15 && i < 25) { item.price_cents = PAID_PRICES[i % 4]; paidCount++; } // adventures 15-24 paid
  else if (i >= 50 && i < 55) { item.price_cents = 199; paidCount++; } // 5 paid monsters
  else if (i >= 55 && i < 65) { item.price_cents = PAID_PRICES[(i - 55) % 3 + 1]; paidCount++; } // 10 paid races/subclasses
  else if (i >= 85 && i < 95) { item.price_cents = PAID_PRICES[i % 2]; paidCount++; } // 10 paid maps
  else { freeCount++; }
});

console.log(`Content ready: ${ITEMS.length} items (${freeCount} free, ${paidCount} paid)`);

// ========================================================================
// MAIN
// ========================================================================

async function main() {
  fs.mkdirSync(COVER_DIR, { recursive: true });

  // Load existing manifest for resume
  let manifest = {};
  if (RESUME && fs.existsSync(MANIFEST_PATH)) {
    manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, 'utf8'));
  }

  // Login
  const user = await login();

  // Process items
  let success = 0, failed = 0;
  for (let i = 0; i < ITEMS.length; i++) {
    const item = ITEMS[i];
    const key = slug(item.title);

    // Skip if already done (resume mode)
    if (RESUME && manifest[key] && manifest[key].id) {
      console.log(`[${i + 1}/${ITEMS.length}] ${item.title} — already done, skipping`);
      success++;
      continue;
    }

    console.log(`[${i + 1}/${ITEMS.length}] ${item.title} (${item.price_cents ? '$' + (item.price_cents / 100).toFixed(2) : 'Free'})`);

    // Generate cover art
    const coverFile = await generateCover(item.title, item.art_prompt, i);
    await sleep(DELAY);

    if (DRY_RUN) {
      console.log('  [dry run] would insert');
      manifest[key] = { cover: coverFile, dryRun: true };
      success++;
      continue;
    }

    // Insert listing
    try {
      const row = {
        creator_id: user.id,
        creator_name: CREATOR_NAME,
        status: 'published',
        kind: item.kind,
        title: item.title,
        summary: item.summary,
        description: item.description,
        price_cents: item.price_cents,
        edition: item.edition || '5e-2024',
        origin: item.origin || 'original',
        license: item.license || 'cc-by-4.0',
        attribution: '',
        rights_confirmed: true,
        level_min: item.level_min || null,
        level_max: item.level_max || null,
        genre: item.genre || '',
        theme: item.theme || '',
        tags: item.tags || [],
        cover_path: null,
        preview_paths: [],
        files: [],
        submitted_at: new Date().toISOString(),
        published_at: new Date().toISOString(),
      };

      const result = await insertListing(row);
      const listing = Array.isArray(result) ? result[0] : result;

      // Upload cover if we have one
      if (coverFile) {
        try {
          const localPath = path.join(COVER_DIR, coverFile);
          const storagePath = await uploadCover(user.id, listing.id, localPath);
          // Update listing with cover path
          await sbFetch('/rest/v1/marketplace_listings?id=eq.' + listing.id, {
            method: 'PATCH',
            headers: { 'Prefer': 'return=minimal' },
            body: JSON.stringify({ cover_path: storagePath }),
          });
          console.log('  cover uploaded');
        } catch (e) {
          console.log('  cover upload failed: ' + e.message);
        }
      }

      manifest[key] = { id: listing.id, cover: coverFile };
      success++;
      console.log('  inserted: ' + listing.id);
    } catch (e) {
      console.error('  INSERT FAILED: ' + e.message);
      manifest[key] = { error: e.message, cover: coverFile };
      failed++;
    }

    // Save manifest after each item
    fs.writeFileSync(MANIFEST_PATH, JSON.stringify(manifest, null, 2));
  }

  console.log(`\nDone. ${success} succeeded, ${failed} failed.`);
  console.log('Manifest saved to ' + MANIFEST_PATH);
}

main().catch(e => { console.error('Fatal: ' + e.message); process.exit(1); });
